{"content": "import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const asar = 'C:\\Users\\24380\\AppData\\Local\\Programs\\DeepSeek Harness\\resources\\app.asar';
const buf = readFileSync(asar);
const jsonSize = buf.readUInt32LE(12);
const header = JSON.parse(buf.subarray(16, 16 + jsonSize).toString('utf8'));
const dataStart = 16 + jsonSize;

function lookup(p) {
  const parts = p.replace(/^\//, '').split('/');
  let node = header;
  for (const part of parts) {
    if (node.files && node.files[part]) node = node.files[part];
    else return null;
  }
  return node;
}

const [, , tar, ...outs] = process.argv;
for (const out of outs) {
  const entry = lookup(tar);
  if (!entry || entry.files) {
    console.error('not found: ' + tar);
    continue;
  }
  mkdirSync(dirname(out), { recursive: true });
  writeFileSync(out, buf.subarray(dataStart + Number(entry.offset), dataStart + Number(entry.offset) + entry.size));
  console.log(`wrote ${out} (${entry.size} bytes)`);
}
", "file_path": "C:\Users\24380\Documents\deepseek-harness\default-workspace\extract-asar.mjs"}

