{"content": "import { readFileSync } from 'node:fs';

const asar = 'C:\\Users\\24380\\AppData\\Local\\Programs\\DeepSeek Harness\\resources\\app.asar';
const buf = readFileSync(asar);
const jsonSize = buf.readUInt32LE(12);
const header = JSON.parse(buf.subarray(16, 16 + jsonSize).toString('utf8'));
const dataStart = 16 + jsonSize;

const files = [];
(function walk(node, prefix) {
  for (const [k, v] of Object.entries(node.files || {})) {
    if (v.files) walk(v, prefix + '/' + k);
    else files.push({ name: prefix + '/' + k, offset: Number(v.offset), size: v.size });
  }
})(header, '');

const needles = process.argv.slice(2).map((n) => Buffer.from(n, 'utf8'));
for (const f of files) {
  if (!/\.(js|mjs|cjs|json|md)$/.test(f.name)) continue;
  const slice = buf.subarray(dataStart + f.offset, dataStart + f.offset + f.size);
  const counts = needles.map((n) => {
    let c = 0;
    let i = 0;
    while ((i = slice.indexOf(n, i)) !== -1) { c++; i += n.length; }
    return c;
  });
  if (counts.some((c) => c > 0)) {
    console.log(counts.map((c, k) => `${process.argv[2 + k]}=${c}`).join(' ') + '  ' + f.name);
  }
}
