{"content": "import { readFileSync } from 'node:fs';

const asar = 'C:\\Users\\24380\\AppData\\Local\\Programs\\DeepSeek Harness\\resources\\app.asar';
const buf = readFileSync(asar);
const jsonSize = buf.readUInt32LE(12);
const header = JSON.parse(buf.subarray(16, 16 + jsonSize).toString('utf8'));
const dataStart = 16 + jsonSize;

const files = [];
(function walk(node, prefix) {
  for (const [k, v] of Object.entries(node.files || {})) {
    if (v.files) walk(v, prefix + '/' + k);
    else files.push({ name: prefix + '/' + k, offset: Number(v.offset), size: v.size });
  }
})(header, '');

const pattern = new RegExp(process.argv[2], 'i');
const ctx = Number(process.argv[3] ?? 160);
for (const f of files) {
  if (!/\.(js|mjs|cjs|json|md|ya?ml|txt)$/.test(f.name)) continue;
  const text = buf.subarray(dataStart + f.offset, dataStart + f.offset + f.size).toString('utf8');
  let m;
  const g = new RegExp(pattern.source, 'gi');
  let printed = 0;
  while ((m = g.exec(text)) && printed < 3) {
    const s = Math.max(0, m.index - ctx);
    const e = Math.min(text.length, m.index + ctx);
    console.log(`### ${f.name} @${m.index}\n${text.slice(s, e).replace(/\n+/g, ' | ')}\n`);
    printed++;
  }
}
", "file_path": "C:\Users\24380\Documents\deepseek-harness\default-workspace\grep-asar.mjs"}

