  Where-Object { $_.FullName -notlike "*dsh-runtimes*" -and $_.Length -gt 20000 } |
  Sort-Object LastWriteTime -Descending | Select-Object -First 60
foreach ($f in $files) {
  try {
    $fs = [System.IO.File]::OpenRead($f.FullName)
    $buf = New-Object byte[] 8
    $null = $fs.Read($buf, 0, 8)
    $fs.Close()
  } catch { continue }
  $hex = ($buf | ForEach-Object { $_.ToString("X2") }) -join ' '
  $type = switch -Wildcard ($hex) {
