{"command": "cd "C:\Users\24380\Documents\deepseek-harness\default-workspace"
@'
import fs from "node:fs";
import path from "node:path";

const root = "C:\\Users\\24380\\.dsh";
const sessRoot = path.join(root, "sessions");
const cacheRoot = path.join(root, "storages", "session_projcache", "sessions");
const rows = [];

for (const group of fs.readdirSync(sessRoot)) {
  const gdir = path.join(sessRoot, group);
  if (!fs.statSync(gdir).isDirectory()) continue;
  for (const id of fs.readdirSync(gdir)) {
    const dir = path.join(gdir, id);
    let stat;
    try { stat = fs.statSync(dir); } catch { continue; }
    if (!stat.isDirectory()) continue;
    const file = path.join(dir, "session.v4.jsonl.zstd");
    let size = 0, mtime = stat.mtime;
    try { const s = fs.statSync(file); size = s.size; mtime = s.mtime; } catch {}
    let title = "", cwd = "";
    try {
      const cache = JSON.parse(fs.readFileSync(path.join(cacheRoot, id + ".json"), "utf8"));
      title = cache?.record?.rows?.title?.val ?? "";
      cwd = cache?.record?.identity?.cwd ?? "";
    } catch {}
    rows.push({ id, group, cwd, title, size, mtime });
  }
}
rows.sort((a, b) => b.mtime - a.mtime);
console.log("count", rows.length);
for (const r of rows) {
  console.log([r.id, (r.size / 1048576).toFixed(2) + "MB", r.mtime.toISOString().slice(0, 16).replace("T", " "), r.cwd, JSON.stringify(r.title.slice(0, 46))].join(" | "));
}
