{"command": "cd "C:\Users\24380\Documents\deepseek-harness\default-workspace"
@'
import fs from "node:fs";
import path from "node:path";
import { zstdDecompressSync } from "node:zlib";

const root = "C:\\Users\\24380\\.dsh\\sessions";
const ids = [
  "session-e31a9d07-7343-48e9-8f4e-ec2f606bc77b",
  "54cee4ec-8c92-4ec8-9393-000f8f130e53",
  "a686f24e-3c01-4c53-8c82-7cbd7c731b21",
  "4904199e-6009-462d-a447-600e24bd1aad",
];

const ops = [];
for (const group of fs.readdirSync(root)) {
  for (const id of ids) {
    const p = `${root}\\${group}\\${id}\\session.v4.jsonl.zstd`;
    if (!fs.existsSync(p)) continue;
    for (const line of zstdDecompressSync(fs.readFileSync(p)).toString("utf8").split("\n")) {
      if (!line) continue;
      let e; try { e = JSON.parse(line); } catch { continue; }
      if (e.type !== "tool/call") continue;
      const n = e.data.name;
      if (n !== "write" && n !== "edit") continue;
      let a; try { a = JSON.parse(e.data.arguments); } catch { continue; }
      ops.push({ t: e.time, id, name: n, args: a });
    }
  }
}
ops.sort((x, y) => x.t - y.t);
console.log("ops", ops.length);

const files = new Map();
const results = [];
for (const op of ops) {
  const p = op.args.file_path ?? op.args.path;
  if (!p) continue;
  const key = p.toLowerCase();
  if (op.name === "write") {
    files.set(key, { path: p, content: op.args.content ?? "" });
    results.push(["write", p, (op.args.content ?? "").length]);
  } else {
    const cur = files.get(key);
    if (!cur) { results.push(["edit-miss", p, 0]); continue; }
    const oldS = op.args.old_string ?? "";
    const newS = op.args.new_string ?? "";
    if (!cur.content.includes(oldS)) { results.push(["edit-nomatch", p, 0]); continue; }
    cur.content = op.args.replace_all ? cur.content.split(oldS).join(newS) : cur.content.replace(oldS, newS);
    results.push(["edit", p, newS.length]);
  }
}
const outDir = "recovered";
fs.mkdirSync(outDir, { recursive: true });
for (const [, f] of files) {
  const rel = f.path.replace(/^[A-Za-z]:\\/, "").replace(/[\\/:]/g, "_");
  fs.writeFileSync(path.join(outDir, rel), f.content);
  console.log("saved", rel, f.content.length);
}
const issues = results.filter((r) => r[0].includes("miss") || r[0].includes("nomatch"));
console.log("issue count", issues.length);
for (const i of issues.slice(0, 20)) console.log("  ", i.join(" "));
'@ | Set-Content -Encoding utf8 replay_logs.mjs
node replay_logs.mjs", "description": "Replay writes and edits to recover previous scripts"}

