content.arguments:
{"content": "param(
    [switch]$Check,
    [string]$ProfileDir = "$PSScriptRoot\edge-profile",
    [int]$Port = 9222
)

$ErrorActionPreference = "Stop"

$edgeCandidates = @(
    "${env:ProgramFiles(x86)}\Microsoft\Edge\Application\msedge.exe",
    "$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe"
)
$edge = $edgeCandidates | Where-Object { Test-Path $_ } | Select-Object -First 1
if (-not $edge) { throw "找不到 msedge.exe，请把 Edge 路径告诉我" }

if ($Check) {
    try {
        $pages = Invoke-RestMethod -Uri "http://127.0.0.1:$Port/json/list" -TimeoutSec 5
        Write-Host "调试端口可用，当前标签页：" -ForegroundColor Green
        foreach ($p in $pages) {
            if ($p.type -eq "page") { Write-Host ("  {0}  {1}" -f $p.title, $p.url) }
        }
    } catch {
        Write-Host "调试端口连不上。请先用不带 -Check 的方式启动浏览器并登录。" -ForegroundColor Yellow
        exit 1
    }
    exit 0
}

New-Item -ItemType Directory -Force -Path $ProfileDir | Out-Null

$args = @(
    "--remote-debugging-port=$Port",
    "--remote-debugging-address=127.0.0.1",
    "--user-data-dir=$ProfileDir",
    "--no-first-run",
    "--no-default-browser-check",
    "https://e.waimai.meituan.com/",
    "https://napos.ele.me/"
)

Write-Host "启动 Edge（独立配置目录：$ProfileDir）..." -ForegroundColor Cyan
Start-Process -FilePath $edge -ArgumentList $args
Write-Host "已启动。请在弹出的窗口里登录两个后台，登录完回来告诉我。" -ForegroundColor Green
", "file_path": "C:\Users\24380\Documents\deepseek-harness\default-workspace\meituan-agent\start-browser.ps1"}

