{"content": """"在美团商家后台里用 JS 点击菜单（绕过 hover/遮挡），并记录接口返回。

用法：
    python meituan_nav.py "订单管理" "全部订单"
"""

from __future__ import annotations

import json
import re
import sys
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

sys.stdout.reconfigure(encoding="utf-8", errors="replace")

CDP_URL = "http://127.0.0.1:9222"
OUT = Path(__file__).with_name("data") / "spy"

JS_CLICK = """
(text) => {
  const nodes = Array.from(document.querySelectorAll('span, div, li, a'));
  const hit = nodes.filter(n => (n.textContent || '').trim() === text);
  if (!hit.length) return 'not-found';
  const el = hit[hit.length - 1];
  let target = el;
  for (let i = 0; i < 4 && target.parentElement; i++) {
    if (target.tagName === 'LI' || target.getAttribute('id')) break;
    target = target.parentElement;
  }
  target.dispatchEvent(new MouseEvent('mouseover', {bubbles: true}));
  target.dispatchEvent(new MouseEvent('mousedown', {bubbles: true}));
  target.dispatchEvent(new MouseEvent('mouseup', {bubbles: true}));
  target.click();
  return 'clicked:' + target.tagName + ':' + (target.id || '');
}
"""


def main() -> int:
    steps = sys.argv[1:]
    if not steps:
        print('usage: python meituan_nav.py "订单管理" "全部订单"')
        return 2

    stamp = time.strftime("%Y%m%d-%H%M%S")
    outdir = OUT / stamp
    outdir.mkdir(parents=True, exist_ok=True)
    records: list[dict] = []

    def on_response(resp):
        try:
            req = resp.request
            if req.resource_type not in ("xhr", "fetch"):
                return
            body = None
            try:
                body = resp.text()[:200_000]
            except Exception:  # noqa: BLE001
                pass
            records.append({"url": resp.url, "status": resp.status, "method": req.method,
                            "post": (req.post_data or "")[:3000], "body": body})
        except Exception:  # noqa: BLE001
            pass

    with sync_playwright() as p:
        browser = p.chromium.connect_over_cdp(CDP_URL)
        ctx = browser.contexts[0]
        page = ctx.pages[0]
        page.on("response", on_response)

        for text in steps:
            result = page.evaluate(JS_CLICK, text)
            print(f"click {text}: {result}")
            page.wait_for_timeout(3000)

        page.wait_for_timeout(6000)
        print("page:", page.title(), "|", page.url)
        print("captured:", len(records))

        (outdir / "responses.json").write_text(json.dumps(records, ensure_ascii=False, indent=1), encoding="utf-8")
        (outdir / "page.txt").write_text(page.inner_text("body"), encoding="utf-8")
        (outdir / "page.html").write_text(page.content(), encoding="utf-8")

        summary: dict[str, int] = {}
        for r in records:
            key = re.sub(r"\?.*$", "", r["url"])
            summary[key] = summary.get(key, 0) + 1
        for url, count in sorted(summary.items(), key=lambda kv: -kv[1])[:40]:
            print(f"  {count:3d}  {url}")
        print("saved ->", outdir)
        browser.close()
    return 0


if __name__ == "__main__":
    sys.exit(main())
