@'
from playwright.sync_api import sync_playwright
import sys, json, re, time
sys.stdout.reconfigure(encoding="utf-8", errors="replace")

recs = []
with sync_playwright() as p:
    b = p.chromium.connect_over_cdp("http://127.0.0.1:9222")
    pg = b.contexts[0].pages[0]

    def on_resp(r):
        try:
            if r.request.resource_type not in ("xhr", "fetch"):
                return
            body = None
            try:
                body = r.text()[:200000]
            except Exception:
                pass
            recs.append({"url": r.url, "status": r.status, "post": (r.request.post_data or "")[:1500], "body": body})
        except Exception:
            pass

    pg.on("response", on_resp)
    pg.reload(wait_until="domcontentloaded", timeout=45000)
    pg.wait_for_timeout(9000)

    print("frames:")
    for i, f in enumerate(pg.frames):
        print(f"  [{i}] {f.url[:120]}")
        try:
            t = f.inner_text('body')[:200].replace('\n', ' | ')
            if t.strip():
                print("       text:", t)
        except Exception:
            pass

    summary = {}
    for r in recs:
        k = re.sub(r"\?.*$", "", r["url"])
        summary[k] = summary.get(k, 0) + 1
    print("\napis:", len(recs))
    for k, c in sorted(summary.items(), key=lambda kv: -kv[1])[:30]:
        print(f"  {c:3d}  {k}")
    json.dump(recs, open("data/spy/reload_orders.json", "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    b.close()
