content.arguments:
{"content": """"在淘宝闪购商家版（melody.shop.ele.me）里按文字点击导航，并记录接口返回。

用法：
    python ele_nav.py "订单管理" "订单查询"
"""

from __future__ import annotations

import json
import re
import sys
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

sys.stdout.reconfigure(encoding="utf-8", errors="replace")

CDP_URL = "http://127.0.0.1:9222"
OUT = Path(__file__).with_name("data") / "spy"


def click_text(page, text: str) -> str:
    """优先真实鼠标点击；失败则用 JS 派发点击事件。"""
    try:
        loc = page.get_by_text(text, exact=True).first
        loc.click(timeout=6000)
        return "mouse"
    except Exception:  # noqa: BLE001
        pass
    try:
        return page.evaluate(
            """(t) => {
                const nodes = Array.from(document.querySelectorAll('a,li,span,div'));
                const hits = nodes.filter(n => (n.textContent||'').trim() === t);
                if (!hits.length) return 'not-found';
                const el = hits[hits.length - 1];
                let target = el;
                for (let i = 0; i < 3 && target.parentElement; i++) target = target.parentElement;
                target.dispatchEvent(new MouseEvent('mouseover', {bubbles: true}));
                target.click();
                return 'js';
            }""",
            text,
        )
    except Exception as exc:  # noqa: BLE001
        return f"error:{type(exc).__name__}"


def main() -> int:
    steps = sys.argv[1:]
    if not steps:
        print('usage: python ele_nav.py "订单管理" "订单查询"')
        return 2

    stamp = time.strftime("%Y%m%d-%H%M%S")
    outdir = OUT / f"ele-{stamp}"
    outdir.mkdir(parents=True, exist_ok=True)
    records: list[dict] = []

    def on_response(resp):
        try:
            req = resp.request
            if req.resource_type not in ("xhr", "fetch"):
                return
            body = None
            try:
                body = resp.text()[:300_000]
            except Exception:  # noqa: BLE001
                pass
            records.append({"url": resp.url, "status": resp.status, "method": req.method,
                            "post": (req.post_data or "")[:3000], "body": body})
        except Exception:  # noqa: BLE001
            pass

    with sync_playwright() as p:
        browser = p.chromium.connect_over_cdp(CDP_URL)
        ctx = browser.contexts[0]
        page = [pg for pg in ctx.pages if "melody.shop.ele.me" in pg.url][-1]
        page.on("response", on_response)

        for text in steps:
            how = click_text(page, text)
            print(f"click {text}: {how} | url now: {page.url[-80:]}")
            page.wait_for_timeout(3500)

        page.wait_for_timeout(5000)
        print("\nfinal url:", page.url)
        try:
            print("text:", page.inner_text("body")[:400].replace("\n", " | "))
        except Exception:  # noqa: BLE001
            pass

        (outdir / "responses.json").write_text(json.dumps(records, ensure_ascii=False, indent=1), encoding="utf-8")
        (outdir / "page.html").write_text(page.content(), encoding="utf-8")
        print("captured:", len(records))
        summary: dict[str, int] = {}
        for r in records:
            summary[re.sub(r"\?.*$", "", r["url"])] = summary.get(re.sub(r"\?.*$", "", r["url"]), 0) + 1
        for url, count in sorted(summary.items(), key=lambda kv: -kv[1])[:30]:
            print(f"  {count:3d}  {url}")
        print("saved ->", outdir)
        browser.close()
    return 0


if __name__ == "__main__":
    sys.exit(main())
