from playwright.sync_api import sync_playwright
import sys, json, collections
sys.stdout.reconfigure(encoding="utf-8", errors="replace")

with sync_playwright() as p:
    b = p.chromium.connect_over_cdp("http://127.0.0.1:9222")
    pg = [x for x in b.contexts[0].pages if "e.waimai.meituan.com" in x.url][-1]
    f = [x for x in pg.frames if "orderbusiness" in x.url and x != pg.main_frame][-1]
    data = f.evaluate("""() => {
        const counts = {};
        document.querySelectorAll('*').forEach(e => {
            const c = (e.className || '').toString();
            if (c && c.length < 60) counts[c] = (counts[c] || 0) + 1;
        });
        const repeating = Object.entries(counts).filter(([, n]) => n >= 15 && n <= 40).sort((a, b) => b[1] - a[1]).slice(0, 25);
        return repeating;
    }""")
    for cls, n in data:
        print(n, cls)
    b.close()
