@'
import json
recs = json.load(open("data/spy/mt_page_resp.json", encoding="utf-8"))
big = max(recs, key=lambda r: len(r["body"] or ""))
o = json.loads(big["body"])["data"]["orderList"][0]

hits = []
def walk(node, path=""):
    if isinstance(node, dict):
        for k, v in node.items():
            p = f"{path}.{k}" if path else k
            if any(w in k.lower() for w in ("amount", "price", "income", "fee", "total", "pay", "money", "cost")):
                if isinstance(v, (int, float, str)):
                    hits.append((p, v))
            walk(v, p)
    elif isinstance(node, list):
        for i, v in enumerate(node[:3]):
            walk(v, f"{path}[{i}]")
    elif isinstance(node, str) and node.startswith("{"):
        try:
            walk(json.loads(node), path + "(json)")
        except Exception:
            pass

walk(o)
for p, v in hits[:60]:
    print(f"{p} = {v}")
print("total hits", len(hits))
