content.arguments:
{"content": """"采集美团外卖商家后台的历史订单（按日期区间），解析后写入本地 SQLite。

原理：在已登录的商家后台页面里，用页面自身的 fetch 调用订单列表接口
（同源、带 cookie），因此不需要破解风控签名。

用法：
    python collect_meituan.py --start 2026-11-10 --end 2026-11-10
    python collect_meituan.py --days 7
"""

from __future__ import annotations

import argparse
import json
import sys
import time
from datetime import date, datetime, timedelta
from pathlib import Path

from playwright.sync_api import sync_playwright

sys.path.insert(0, str(Path(__file__).parent))
import db  # noqa: E402

sys.stdout.reconfigure(encoding="utf-8", errors="replace")

CDP_URL = "http://127.0.0.1:9222"
API = "/gw/api/unified/r/order/list/page/history"
PAGE_SIZE = 10

FETCH_JS = """
async ({api, start, end, pageNum, pageSize}) => {
    const url = api + "?region_id=1000350300&region_version=1792542949";
    const body = new URLSearchParams({
        tag: "allOrder",
        pageParam: JSON.stringify({pageSize, pageNum, sort: 0, nextLabel: null, lastLabel: null, direction: 0}),
        extParam: JSON.stringify({phfRollback: 0, searchTag: -1}),
        startDate: start,
        endDate: end,
    });
    const r = await fetch(url, {
        method: "POST",
        credentials: "include",
        headers: {"Content-Type": "application/x-www-form-urlencoded; charset=UTF-8"},
        body: body.toString(),
    });
    const text = await r.text();
    return {status: r.status, text};
}
"""


def popen_page():
    pw = sync_playwright().start()
    browser = pw.chromium.connect_over_cdp(CDP_URL, timeout=60000)
    pages = [pg for ctx in browser.contexts for pg in ctx.pages]
    page = [pg for pg in pages if "e.waimai.meituan.com" in pg.url]
    if not page:
        raise SystemExit("没有找到美团后台标签页，请先启动浏览器并登录")
    return pw, browser, page[0]


def fetch_page(page, start: str, end: str, page_num: int) -> dict:
    res = page.evaluate(FETCH_JS, {"api": API, "start": start, "end": end,
                                   "pageNum": page_num, "pageSize": PAGE_SIZE})
    if res["status"] != 200:
        raise RuntimeError(f"HTTP {res['status']}: {res['text'][:200]}")
    return json.loads(res["text"])


def _json_field(value):
    if isinstance(value, str) and value.strip().startswith("{"):
        try:
            return json.loads(value)
        except Exception:  # noqa: BLE001
            return {}
    return value or {}


def parse_order(raw: dict) -> dict:
    common = _json_field(raw.get("commonInfo"))
    info = _json_field(raw.get("orderInfo"))
    unified = info.get("unifiedOrderInfo", {}) or {}
    basic = unified.get("basicVo", {}) or {}
    charge = (info.get("chargeInfo", {}) or {}).get("fixedSettlementInfo", {}) or {}
    food = info.get("foodInfo", {}) or {}

    items = []
    for cart in food.get("cartDetailVos", []) or []:
        for detail in cart.get("details", []) or []:
            name = detail.get("foodName") or detail.get("name") or ""
            if not name:
                continue
            qty = detail.get("quantity") or detail.get("count") or 1
            price = detail.get("foodPrice") or detail.get("originFoodPrice") or 0
            items.append({"name": name, "qty": qty, "price": float(price or 0)})

    order_time = basic.get("orderTime") or common.get("order_time")
    created = datetime.fromtimestamp(order_time).strftime("%Y-%m-%d %H:%M:%S") if order_time else None

    cents = lambda v: int(round(float(v or 0) * 100))  # noqa: E731

    return {
        "platform": "meituan",
        "order_no": str(common.get("wm_order_id_view") or unified.get("wmOrderId") or raw.get("wmOrderViewId")),
        "shop": unified.get("poiName") or "兵哥烧烤",
        "created_at": created,
        "status": unified.get("statusDesc") or str(basic.get("status")),
        "amount_cents": cents(charge.get("userPayTotalAmount")),
        "discount_cents": cents(abs(float(charge.get("activityAmount") or 0))),
        "packing_cents": cents(charge.get("packageBagMoney")),
        "delivery_cents": cents(charge.get("shippingFee")),
        "commission_cents": cents(charge.get("commisionAmount")),
        "refund_cents": 0,
        "items_json": json.dumps(items, ensure_ascii=False),
        "fetched_at": datetime.now().strftime("%Y-%m-%dT%H:%M:%S"),
        "settle_cents": cents(charge.get("settleAmount") or charge.get("orderSettleAmount")),
        "food_cents": cents(charge.get("foodAmount")),
        "day_seq": unified.get("dayseq") or common.get("wm_poi_order_dayseq"),
    }


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--start")
    ap.add_argument("--end")
    ap.add_argument("--days", type=int, default=None, help="采集最近 N 天（含今天）")
    ap.add_argument("--dry-run", action="store_true")
    args = ap.parse_args()

    if args.days:
        end = date.today()
        start = end - timedelta(days=args.days - 1)
    else:
        if not (args.start and args.end):
            ap.error("需要 --start/--end 或 --days")
        start = date.fromisoformat(args.start)
        end = date.fromisoformat(args.end)

    db.init()
    pw, browser, page = popen_page()
    total = 0
    try:
        day = start
        while day <= end:
            iso = day.isoformat()
            page_num = 1
            rows = []
            while True:
                payload = fetch_page(page, iso, iso, page_num)
                data = payload.get("data") or {}
                orders = data.get("orderList") or []
                for raw in orders:
                    try:
                        rows.append(parse_order(raw))
                    except Exception as exc:  # noqa: BLE001
                        print("  parse error:", exc)
                info = data.get("pageInfo") or {}
                pages = int(info.get("pageCount") or 1)
                print(f"{iso} page {page_num}/{pages}: {len(orders)} orders")
                if page_num >= pages:
                    break
                page_num += 1
                time.sleep(1.2)

            if not args.dry_run and rows:
                with db.connect() as conn:
                    n = db.upsert_orders(conn, rows)
                    for r in rows:
                        for item in json.loads(r["items_json"]):
                            conn.execute(
                                "INSERT INTO order_items (platform, order_no, sku_name, qty, unit_price_cents, amount_cents)"
                                " VALUES (?,?,?,?,?,?) ON CONFLICT(platform, order_no, sku_name) DO UPDATE SET"
                                " qty=excluded.qty, unit_price_cents=excluded.unit_price_cents, amount_cents=excluded.amount_cents",
                                (r["platform"], r["order_no"], item["name"], item["qty"],
                                 int(round(item["price"] * 100)), int(round(item["price"] * item["qty"] * 100))),
                            )
                    db.log_run(conn, "meituan", "orders", iso, datetime.now().isoformat(timespec="seconds"),
                               "ok", n, f"{iso} 采集 {n} 单")
                total += n
            elif args.dry_run:
                for r in rows[:3]:
                    print(json.dumps(r, ensure_ascii=False)[:300])
            day += timedelta(days=1)
    finally:
        browser.close()
        pw.stop()

    print(f"\n完成，写入 {total} 单")
    return 0


if __name__ == "__main__":
    sys.exit(main())
