        "amount_cents": cents(charge.get("userPayTotalAmount")),
        "discount_cents": cents(abs(float(charge.get("activityAmount") or 0))),
        "packing_cents": cents(charge.get("packageBagMoney")),
        "delivery_cents": cents(charge.get("shippingFee")),
        "commission_cents": cents(charge.get("commisionAmount")),
        "refund_cents": 0,
        "items_json": json.dumps(items, ensure_ascii=False),
        "fetched_at": datetime.now().strftime("%Y-%m-%dT%H:%M:%S"),
        "settle_cents": cents(charge.get("settleAmount") or charge.get("orderSettleAmount")),
        "food_cents": cents(charge.get("foodAmount")),
        "day_seq": unified.get("dayseq") or common.get("wm_poi_order_dayseq"),
    }


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--start")
    ap.add_argument("--end")
    ap.add_argument("--days", type=int, default=None, help="采集最近 N 天（含今天）")
    ap.add_argument("--dry-run", action="store_true")
    args = ap.parse_args()

    if args.days:
        end = date.today()
        start = end - timedelta(days=args.days - 1)
    else:
        if not (args.start and args.end):
            ap.error("需要 --start/--end 或 --days")
        start = date.fromisoformat(args.start)
        end = date.fromisoformat(args.end)

    db.init()
    pw, browser, page = popen_page()
    total = 0
    try:
        day = start
        while day <= end:
            iso = day.isoformat()
            page_num = 1
            rows = []
            while True:
                payload = fetch_page(page, iso, iso, page_num)
                data = payload.get("data") or {}
                orders = data.get("orderList") or []
                for raw in orders:
                    try:
                        rows.append(parse_order(raw))
                    except Exception as exc:  # noqa: BLE001
                        print("  parse error:", exc)
                info = data.get("pageInfo") or {}
                pages = int(info.get("pageCount") or 1)
                print(f"{iso} page {page_num}/{pages}: {len(orders)} orders")
                if page_num >= pages:
                    break
                page_num += 1
                time.sleep(1.2)

            if not args.dry_run and rows:
                with db.connect() as conn:
                    n = db.upsert_orders(conn, rows)
                    for r in rows:
                        for item in json.loads(r["items_json"]):
                            conn.execute(
                                "INSERT INTO order_items (platform, order_no, sku_name, qty, unit_price_cents, amount_cents)"
                                " VALUES (?,?,?,?,?,?) ON CONFLICT(platform, order_no, sku_name) DO UPDATE SET"
                                " qty=excluded.qty, unit_price_cents=excluded.unit_price_cents, amount_cents=excluded.amount_cents",
                                (r["platform"], r["order_no"], item["name"], item["qty"],
                                 int(round(item["price"] * 100)), int(round(item["price"] * item["qty"] * 100))),
                            )
                    db.log_run(conn, "meituan", "orders", iso, datetime.now().isoformat(timespec="seconds"),
                               "ok", n, f"{iso} 采集 {n} 单")
                total += n
            elif args.dry_run:
                for r in rows[:3]:
                    print(json.dumps(r, ensure_ascii=False)[:300])
            day += timedelta(days=1)
    finally:
        browser.close()
        pw.stop()

    print(f"\n完成，写入 {total} 单")
    return 0


if __name__ == "__main__":
    sys.exit(main())
