from playwright.sync_api import sync_playwright
import sys, pathlib, time, json
sys.stdout.reconfigure(encoding="utf-8", errors="replace")
dl = pathlib.Path.home() / "Downloads"
before = {p.name for p in dl.glob("*")}
recs = []
with sync_playwright() as p:
    b = p.chromium.connect_over_cdp("http://127.0.0.1:9222", timeout=60000)
    pg = [x for x in b.contexts[0].pages if "melody.shop.ele.me" in x.url][-1]
    fr = [f for f in pg.frames if "download-center" in f.url][-1]
    fr.on("response", lambda r: recs.append((r.status, r.url)) if r.request.resource_type in ("xhr","fetch","document") else None)
    ok = fr.evaluate("""() => {
        const row = Array.from(document.querySelectorAll('tr')).find(tr => (tr.innerText||'').includes('门店下载_'));
        if (!row) return 'no-row';
        const span = Array.from(row.querySelectorAll('span')).find(s => (s.textContent||'').trim() === '下载');
        if (!span) return 'no-span';
        span.dispatchEvent(new MouseEvent('mousedown', {bubbles: true}));
        span.dispatchEvent(new MouseEvent('mouseup', {bubbles: true}));
        span.click();
        return 'clicked';
    }""")
    print("click:", ok)
    for _ in range(20):
        new = [x for x in dl.glob("*") if x.name not in before]
        if new:
            print("FILE:", new[0], new[0].stat().st_size)
            break
        time.sleep(1.5)
    else:
        print("no file yet; responses:", recs[-8:])
    b.close()
