    session = ctx.new_cdp_session(pg)
    session.send("Browser.setDownloadBehavior", {"behavior": "allow", "downloadPath": str(out.resolve()), "eventsEnabled": True})
    print("download behavior set ->", out.resolve())
    fr = [f for f in pg.frames if "download-center" in f.url][-1]
    ok = fr.evaluate("""() => {
        const row = Array.from(document.querySelectorAll('tr')).find(tr => (tr.innerText||'').includes('门店下载_'));
        if (!row) return 'no-row';
        const span = Array.from(row.querySelectorAll('span')).find(s => (s.textContent||'').trim() === '下载');
        if (!span) return 'no-span';
        span.click();
        return 'clicked';
    }""")
    print("click:", ok)
    for _ in range(20):
        files = list(out.glob("*"))
        if files:
            print("FILE:", files[0].name, files[0].stat().st_size)
            break
        time.sleep(1.5)
    else:
        print("still nothing:", list(out.glob('*')))
