{"content": """"日报推送通道：企业微信群机器人 / PushPlus / ServerChan，均用标准库实现。

配置放在同目录 config.json：
{
  "channel": "wecom",                       // wecom | pushplus | serverchan | file
  "wecom_webhook": "https://qyapi.weixin.qq.com/cgi-bin/webhook/send?key=xxx",
  "pushplus_token": "",
  "serverchan_key": ""
}
"""

from __future__ import annotations

import json
import sys
import urllib.parse
import urllib.request
from pathlib import Path

sys.stdout.reconfigure(encoding="utf-8", errors="replace")

HERE = Path(__file__).parent
CONFIG = HERE / "config.json"


def load_config() -> dict:
    if CONFIG.exists():
        try:
            return json.loads(CONFIG.read_text(encoding="utf-8"))
        except Exception:  # noqa: BLE001
            pass
    return {}


def _post(url: str, payload: dict | str, form: bool = False) -> str:
    if form:
        body = urllib.parse.urlencode(payload).encode("utf-8")
        headers = {"Content-Type": "application/x-www-form-urlencoded"}
    else:
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        headers = {"Content-Type": "application/json"}
    req = urllib.request.Request(url, data=body, headers=headers, method="POST")
    with urllib.request.urlopen(req, timeout=20) as resp:
        return resp.read().decode("utf-8", errors="replace")


def send_wecom(text: str, cfg: dict) -> str:
    url = cfg.get("wecom_webhook", "")
    if not url:
        raise SystemExit("未配置 wecom_webhook")
    # 企业微信 markdown 上限 4096 字节，超出截断
    payload = {"msgtype": "markdown", "markdown": {"content": text[:3800]}}
    return _post(url, payload)


def send_pushplus(text: str, cfg: dict, title: str = "经营日报") -> str:
    token = cfg.get("pushplus_token", "")
    if not token:
        raise SystemExit("未配置 pushplus_token")
    return _post("https://www.pushplus.plus/send/",
                 {"token": token, "title": title, "content": text, "template": "markdown"})


def send_serverchan(text: str, cfg: dict, title: str = "经营日报") -> str:
    key = cfg.get("serverchan_key", "")
    if not key:
        raise SystemExit("未配置 serverchan_key")
    return _post(f"https://sctapi.ftqq.com/{key}.send", {"title": title, "desp": text}, form=True)


def push(text: str, title: str = "经营日报") -> str:
    cfg = load_config()
    channel = cfg.get("channel") or "file"
    if channel == "wecom":
        return send_wecom(text, cfg)
    if channel == "pushplus":
        return send_pushplus(text, cfg, title)
    if channel == "serverchan":
        return send_serverchan(text, cfg, title)
    out = HERE / "reports" / "last_push.txt"
    out.parent.mkdir(exist_ok=True)
    out.write_text(text, encoding="utf-8")
    return f"未配置推送通道，已写入 {out}"


if __name__ == "__main__":
    body = sys.stdin.read() if not sys.argv[1:] else " ".join(sys.argv[1:])
    print(push(body))
", "file_path": "C:\Users\24380\Documents\deepseek-harness\default-workspace\meituan-agent\notify.py"}

