{"content": "param(
    [string]$Date = ""
)

# 每天定时跑：拉起浏览器 → 采集 → 出日报 → 推送 → 关掉浏览器
$ErrorActionPreference = "Continue"
$here = $PSScriptRoot
$py = "C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe"
$log = Join-Path $here "logs"
New-Item -ItemType Directory -Force -Path $log | Out-Null
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$logFile = Join-Path $log "daily-$stamp.log"

function Write-Log($msg) {
    $line = "[{0}] {1}" -f (Get-Date -Format "HH:mm:ss"), $msg
    Write-Host $line
    Add-Content -Path $logFile -Value $line -Encoding utf8
}

Write-Log "开始：日报任务"

# 1) 浏览器（带调试端口，登录态复用）
$alive = $false
try {
    Invoke-RestMethod -Uri "http://127.0.0.1:9222/json/version" -TimeoutSec 3 | Out-Null
    $alive = $true
    Write-Log "浏览器已在运行"
} catch {
    Write-Log "启动浏览器"
    & powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $here "start-browser.ps1")
    for ($i = 0; $i -lt 20; $i++) {
        Start-Sleep -Seconds 2
        try {
            Invoke-RestMethod -Uri "http://127.0.0.1:9222/json/version" -TimeoutSec 3 | Out-Null
            $alive = $true
            break
        } catch { }
    }
}

if (-not $alive) {
    Write-Log "浏览器启动失败，退出"
    exit 1
}

# 2) 采集 + 日报 + 推送
$argsList = @((Join-Path $here "daily.py"))
if ($Date) { $argsList += @("--date", $Date) }
& $py @argsList 2>&1 | ForEach-Object { Write-Log $_ }

$code = $LASTEXITCODE
Write-Log "结束，exit=$code"

# 3) 如果浏览器是脚本拉起的，跑完关掉，避免常驻占用
if (-not $StartedByTask) { }
exit $code
