{"content": "param(
    [switch]$Check,
    [switch]$Silent,
    [string]$ProfileDir = "$PSScriptRoot\edge-profile",
    [int]$Port = 9222
)

$ErrorActionPreference = "Stop"

$edgeCandidates = @(
    "${env:ProgramFiles(x86)}\Microsoft\Edge\Application\msedge.exe",
    "$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe"
)
$edge = $edgeCandidates | Where-Object { Test-Path $_ } | Select-Object -First 1
if (-not $edge) { throw "无法定位 msedge.exe，请把 Edge 的完整路径告诉我" }

if ($Check) {
    try {
        $pages = Invoke-RestMethod -Uri ("http://127.0.0.1:{0}/json/list" -f $Port) -TimeoutSec 5
        Write-Host "调试端口可用，当前标签页：" -ForegroundColor Green
        foreach ($p in $pages) {
            if ($p.type -eq "page") {
                Write-Host ("  [{0}] {1}" -f $p.title, $p.url)
            }
        }
    } catch {
        Write-Host "调试端口连不上。请先不带 -Check 运行本脚本，并在弹出的窗口里登录。" -ForegroundColor Yellow
        exit 1
    }
    exit 0
}

New-Item -ItemType Directory -Force -Path $ProfileDir | Out-Null

$browserArgs = @(
    ("--remote-debugging-port={0}" -f $Port),
    "--remote-debugging-address=127.0.0.1",
    ("--user-data-dir={0}" -f $ProfileDir),
    "--no-first-run",
    "--no-default-browser-check"
)

if ($Silent) {
    # 无窗口运行：不弹窗、不抢焦点，登录态仍从同一个 profile 读取
    $browserArgs += @(
        "--headless=new",
        "--disable-gpu",
        "--window-size=1440,900",
        "--mute-audio"
    )
}

$browserArgs += @(
    "https://e.waimai.meituan.com/",
    "https://melody.shop.ele.me/"
)

if ($Silent) {
    Write-Host "以无窗口模式启动 Edge（调试端口 $Port）" -ForegroundColor Cyan
} else {
    Write-Host ("启动 Edge，独立配置目录：{0}" -f $ProfileDir) -ForegroundColor Cyan
}
Start-Process -FilePath $edge -ArgumentList $browserArgs
if (-not $Silent) {
    Write-Host "已启动。请在弹出的窗口里登录美团和淘宝闪购后台，完成后回来告诉我。" -ForegroundColor Green
}
", "file_path": "C:\Users\24380\Documents\deepseek-harness\default-workspace\meituan-agent\start-browser.ps1"}

