{"content": """"烧烤店数据助手的核心：把「人话问题」翻译成 SQL，再拼成回答。

先不依赖任何大模型也能用（规则匹配），后续可无缝接 DeepSeek 做意图理解。

用法：
    python ask.py "昨天卖了多少"
    python ask.py "近7天哪个菜卖得最好"
"""

from __future__ import annotations

import re
import sqlite3
from datetime import date, timedelta
from pathlib import Path

DB = Path(__file__).with_name("data") / "shop.db"
PLATFORM = {"meituan": "美团", "eleme": "淘宝闪购"}


def conn():
    c = sqlite3.connect(DB)
    c.row_factory = sqlite3.Row
    return c


def yuan(cents) -> str:
    return f"¥{(cents or 0) / 100:,.2f}"


def resolve_range(text: str) -> tuple[str, str, str]:
    """返回 (起, 止, 描述)。"""
    today = date.today()
    if "今天" in text or "今日" in text:
        d = today.isoformat()
        return d, d, "今天"
    if "昨天" in text or "昨日" in text:
        d = (today - timedelta(days=1)).isoformat()
        return d, d, "昨天"
    m = re.search(r"近\s*(\d+)\s*天", text)
    if m:
        n = int(m.group(1))
        start = (today - timedelta(days=n)).isoformat()
        end = (today - timedelta(days=1)).isoformat()
        return start, end, f"近{n}天"
    m = re.search(r"(\d{4}-\d{1,2}-\d{1,2})", text)
    if m:
        d = m.group(1)
        return d, d, d
    d = (today - timedelta(days=1)).isoformat()
    return d, d, "昨天（默认）"


def summary(start: str, end: str) -> str:
    c = conn()
    row = c.execute(
        """SELECT COUNT(*) n, SUM(amount_cents) amt, SUM(settle_cents) settle,
                  SUM(commission_cents) comm
           FROM orders WHERE date(created_at) BETWEEN ? AND ?""",
        (start, end),
    ).fetchone()
    lines = []
    if row and row["n"]:
        n, amt, settle, comm = row["n"], row["amt"] or 0, row["settle"] or 0, row["comm"] or 0
        lines.append(f"共 **{n} 单**，顾客实付 {yuan(amt)}，预计收入 {yuan(settle)}，客单价 {yuan(amt/n)}。")
        lines.append(f"平台佣金 {yuan(comm)}（{comm/amt*100:.1f}%）。")
    else:
        lines.append("这期间没有订单。")
    ele = c.execute(
        """SELECT SUM(orders) o, SUM(gmv_cents) g, SUM(net_cents) s
           FROM daily_metrics WHERE date BETWEEN ? AND ? AND platform='eleme'""",
        (start, end),
    ).fetchone()
    if ele and ele["o"]:
        lines.append(f"淘宝闪购：{ele['o']} 单，营业额 {yuan(ele['g'])}，预计收入 {yuan(ele['s'])}。")
    c.close()
    return "\n".join(lines)


def top_items(start: str, end: str, limit: int = 5, by: str = "amount") -> str:
    order = "a DESC" if by == "amount" else "q DESC"
    c = conn()
    rows = c.execute(
        f"""SELECT sku_name, SUM(qty) q, SUM(amount_cents) a FROM order_items
            WHERE order_no IN (SELECT order_no FROM orders WHERE date(created_at) BETWEEN ? AND ?)
            GROUP BY sku_name ORDER BY {order} LIMIT ?""",
        (start, end, limit),
    ).fetchall()
    c.close()
    if not rows:
        return "这期间没有商品销售记录。"
    lines = [f"卖得最好的 {len(rows)} 个商品："]
    for i, r in enumerate(rows, 1):
        lines.append(f"{i}. {r['sku_name']}　{r['q']:.0f} 份　{yuan(r['a'])}")
    return "\n".join(lines)


def item_sales(name: str, start: str, end: str) -> str:
    c = conn()
    row = c.execute(
        """SELECT SUM(qty) q, SUM(amount_cents) a FROM order_items
           WHERE sku_name LIKE ? AND order_no IN
             (SELECT order_no FROM orders WHERE date(created_at) BETWEEN ? AND ?)""",
        (f"%{name}%", start, end),
    ).fetchone()
    c.close()
    if not row or not row["q"]:
        return f"这期间没查到“{name}”的销量。"
    return f"“{name}”卖了 {row['q']:.0f} 份，合计 {yuan(row['a'])}。"


def hourly(start: str, end: str) -> str:
    c = conn()
    rows = c.execute(
        """SELECT substr(created_at,12,2) h, COUNT(*) n, SUM(amount_cents) a
           FROM orders WHERE date(created_at) BETWEEN ? AND ? GROUP BY h ORDER BY n DESC LIMIT 5""",
        (start, end),
    ).fetchall()
    c.close()
    if not rows:
        return "没有订单。"
    return "高峰时段：" + "，".join(f"{r['h']}点 {r['n']}单" for r in rows)


def answer(text: str) -> str:
    start, end, label = resolve_range(text)
    head = f"【{label}】"

    if any(k in text for k in ("最好", "最火", "卖得最多", "爆款", "top", "TOP")):
        return head + "\n" + top_items(start, end)
    if any(k in text for k in ("时段", "几点", "高峰")):
        return head + "\n" + hourly(start, end)
    m = re.search(r"(.+?)(卖了多少|销量|卖了几份)", text)
    if m:
        name = m.group(1).replace("的", "").strip()
        if name and name not in ("今天", "昨天", "近7天"):
            return head + "\n" + item_sales(name, start, end)
    return head + "\n" + summary(start, end)


if __name__ == "__main__":
    import sys

    sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    q = " ".join(sys.argv[1:]) or "昨天卖了多少"
    print(answer(q))
