    [string]$SendChat = "",
    [string]$SendText = ""
)

# 启动微信 3.9（机器人专用小号）并运行消息适配层
$ErrorActionPreference = "Continue"
$here = $PSScriptRoot
$py = "C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe"
$wx = "C:\Program Files\Tencent\WeChat\WeChat.exe"

if (-not (Get-Process WeChat -ErrorAction SilentlyContinue)) {
    if (Test-Path $wx) {
        Write-Host "启动微信 3.9（小号）..."
        Start-Process -FilePath $wx
        Start-Sleep -Seconds 8
    } else {
