{"content": """"兵哥烧烤 · 经营数据助手（本地网页版）

在店里电脑上运行，手机连同一个 WiFi 打开网页即可提问。

启动：
    python web_app.py                # 默认 0.0.0.0:8000
    python web_app.py --port 8080
"""

from __future__ import annotations

import argparse
import json
import socket
import sys
import urllib.parse
from datetime import date, timedelta
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
import bot_core  # noqa: E402
import report as report_mod  # noqa: E402

sys.stdout.reconfigure(encoding="utf-8", errors="replace")

PAGE = """<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>兵哥烧烤 · 数据助手</title>
<style>
  :root { --bg:#f5f6f8; --card:#fff; --ink:#1f2329; --sub:#8a9099; --brand:#ff6a00; --line:#e8eaed; }
  * { box-sizing:border-box; -webkit-tap-highlight-color:transparent; }
  body { margin:0; background:var(--bg); color:var(--ink);
         font:16px/1.65 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif; }
  header { background:var(--brand); color:#fff; padding:calc(14px + env(safe-area-inset-top)) 16px 14px; }
  header h1 { margin:0; font-size:19px; font-weight:700; letter-spacing:.5px; }
  header p { margin:3px 0 0; font-size:12px; opacity:.85; }
  main { padding:14px 12px 132px; max-width:720px; margin:0 auto; }
  .chips { display:flex; gap:8px; overflow-x:auto; padding-bottom:10px; scrollbar-width:none; }
  .chips::-webkit-scrollbar { display:none; }
  .chip { flex:0 0 auto; border:1px solid var(--line); background:#fff; color:#4a5058;
          padding:8px 13px; border-radius:999px; font-size:13px; }
  .chip:active { background:#f0f1f3; }
  .msg { background:var(--card); border-radius:14px; padding:13px 15px; margin-bottom:10px;
         box-shadow:0 1px 2px rgba(16,24,40,.04); font-size:15px; word-break:break-word; }
  .msg.q { background:#fff3e8; color:#8a4a10; }
  .msg .tag { font-size:11px; color:var(--sub); display:block; margin-bottom:4px; }
  .msg b { color:#111; }
  .dock { position:fixed; left:0; right:0; bottom:0; background:rgba(255,255,255,.96);
          backdrop-filter:blur(8px); border-top:1px solid var(--line);
          padding:10px 12px calc(10px + env(safe-area-inset-bottom)); }
  .row { display:flex; gap:8px; max-width:720px; margin:0 auto; }
  input { flex:1; border:1px solid var(--line); border-radius:12px; padding:12px 14px;
          font-size:16px; outline:none; background:#fafbfc; }
  input:focus { border-color:var(--brand); background:#fff; }
  button { border:0; background:var(--brand); color:#fff; font-size:15px; font-weight:600;
           padding:0 18px; border-radius:12px; }
  button:disabled { opacity:.5; }
  .hint { color:var(--sub); font-size:12px; text-align:center; margin-top:8px; }
</style>
</head>
<body>
<header>
  <h1>兵哥烧烤 · 数据助手</h1>
  <p>美团 + 淘宝闪购 · 本地数据，不上传</p>
</header>
<main id="log">
  <div class="msg"><span class="tag">助手</span>直接问我就行，比如“昨天卖了多少”。<br>下面是常问的几个，点一下就能查。</div>
  <div class="chips">
    <div class="chip">昨天卖了多少</div>
    <div class="chip">今天卖了多少</div>
    <div class="chip">近7天哪个菜卖得最好</div>
    <div class="chip">昨天几点最忙</div>
    <div class="chip">碳烤大鸡翅卖了多少</div>
    <div class="chip">近7天数据</div>
  </div>
</main>
<div class="dock">
