content.arguments:
{"content": "param(
    [int]$Port = 8000,
    [switch]$Open
)

# 一键启动「兵哥烧烤 · 数据助手」网页
$ErrorActionPreference = "Continue"
$here = $PSScriptRoot
$py = "C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe"

# 1) 确保防火墙放行（需要管理员；失败则提示）
$rule = Get-NetFirewallRule -DisplayName "BBQ Data Assistant $Port" -ErrorAction SilentlyContinue
if (-not $rule) {
    try {
        New-NetFirewallRule -DisplayName "BBQ Data Assistant $Port" -Direction Inbound `
            -Protocol TCP -LocalPort $Port -Action Allow -Profile Private,Domain -ErrorAction Stop | Out-Null
        Write-Host "已放行防火墙端口 $Port" -ForegroundColor Green
    } catch {
        Write-Host "未能自动放行防火墙（需要管理员）。若手机打不开，请右键以管理员身份运行本脚本一次。" -ForegroundColor Yellow
    }
}

# 2) 取本机局域网 IP
$ip = (Get-NetIPAddress -AddressFamily IPv4 |
    Where-Object { $_.IPAddress -notlike "127.*" -and $_.PrefixOrigin -ne "WellKnown" } |
    Select-Object -First 1).IPAddress
if (-not $ip) { $ip = "127.0.0.1" }

Write-Host ""
Write-Host "  手机访问： " -NoNewline
Write-Host "http://${ip}:$Port" -ForegroundColor Cyan
Write-Host "  本机访问： http://127.0.0.1:$Port" -ForegroundColor DarkGray
Write-Host ""

if ($Open) { Start-Process "http://127.0.0.1:$Port" }

# 3) 启动服务（占用当前窗口，Ctrl+C 停止）
& $py (Join-Path $here "web_app.py") --port $Port
", "file_path": "C:\Users\24380\Documents\deepseek-harness\default-workspace\meituan-agent\start_web.ps1"}

