{"command": "cd "C:\Users\24380\Documents\deepseek-harness\default-workspace\meituan-agent"
$py = "C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe"
@'
import io
p = "bot_core.py"
s = io.open(p, encoding="utf-8").read()

old = '''def answer(text: str) -> str:
    start, end, label = resolve_range(text)
    head = f"【{label}】"

    if any(k in text for k in ("最好", "最火", "卖得最多", "爆款", "top", "TOP")):
        return head + "\\n" + top_items(start, end)
    if any(k in text for k in ("时段", "几点", "高峰")):
        return head + "\\n" + hourly(start, end)
    m = re.search(r"(.+?)(卖了多少|销量|卖了几份)", text)
    if m:
        name = m.group(1).replace("的", "").strip()
        if name and name not in ("今天", "昨天", "近7天"):
            return head + "\\n" + item_sales(name, start, end)
    return head + "\\n" + summary(start, end)'''

new = '''def match(text: str) -> str | None:
    """规则能直接答的返回答案，答不了返回 None（交给 DeepSeek）。"""
    start, end, label = resolve_range(text)
    head = f"【{label}】"

    if any(k in text for k in ("最好", "最火", "卖得最多", "爆款", "top", "TOP")):
        return head + "\\n" + top_items(start, end)
    if any(k in text for k in ("时段", "几点", "高峰")):
        return head + "\\n" + hourly(start, end)
    m = re.search(r"(.+?)(卖了多少|销量|卖了几份)", text)
    if m:
        name = m.group(1).replace("的", "").strip()
        if name and name not in ("今天", "昨天", "近7天"):
            return head + "\\n" + item_sales(name, start, end)
    if any(k in text for k in ("卖了多少", "多少单", "单量", "营业额", "收入", "客单价", "gmv", "GMV", "数据")):
        return head + "\\n" + summary(start, end)
    return None


def answer(text: str) -> str:
    """先走规则（快、稳），规则覆盖不了再交给 DeepSeek。"""
    hit = match(text)
    if hit is not None:
        return hit
    try:
        import llm
        return llm.ask(text)
    except Exception as exc:  # noqa: BLE001
        fallback = match(text + " 卖了多少")
        return (fallback or "") + f"\\n\\n（智能问答暂时不可用：{type(exc).__name__}）"
'''

assert old in s
s = s.replace(old, new, 1)
io.open(p, "w", encoding="utf-8").write(s)
print("bot_core patched")
