<script>
const state = { range: 'yesterday', tab: 'business' };
const $ = s => document.querySelector(s);

function esc(s) { return String(s).replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }
function fmt(s) { return esc(s).replace(/\\*\\*(.+?)\\*\\*/g, '<b>$1</b>').replace(/\\n/g, '<br>'); }

async function loadDash() {
  const r = await fetch('/api/dashboard?range=' + state.range);
  const j = await r.json();
  const tabs = $('#tabs');
  if (!tabs.children.length) {
    tabs.innerHTML = j.tabs.map(t =>
      `<div class="tab${t.key === state.tab ? ' on' : ''}" data-k="${t.key}">${t.label}</div>`).join('');
    tabs.querySelectorAll('.tab').forEach(el => el.onclick = () => {
      state.tab = el.dataset.k;
      tabs.querySelectorAll('.tab').forEach(x => x.classList.toggle('on', x.dataset.k === state.tab));
      render(j);
    });
  } else {
    tabs.querySelectorAll('.tab').forEach(x => x.classList.toggle('on', x.dataset.k === state.tab));
  }
  window.__dash = j;
  render(j);
}

