  const tab = j.tabs.find(t => t.key === state.tab) || j.tabs[0];
  $('#metaTime').textContent = `已选时间：${j.range.start}${j.range.start === j.range.end ? '' : ' 至 ' + j.range.end}`;
  $('#metaCmp').textContent = j.range.compare;
  $('#grid').innerHTML = tab.metrics.map(m => {
    const cls = m.delta && m.delta.dir ? m.delta.dir : 'flat';
    const arrow = cls === 'up' ? '↑ ' : (cls === 'down' ? '↓ ' : '');
    return `<div class="kpi"><div class="l">${esc(m.label)}</div>
      <div class="v">${esc(m.value)}</div>
      <div class="d ${cls}">${arrow}${esc((m.delta && m.delta.text) || '')}</div></div>`;
  }).join('');
}

document.querySelectorAll('#ranges .range').forEach(el => el.onclick = () => {
  state.range = el.dataset.k;
  document.querySelectorAll('#ranges .range').forEach(x => x.classList.toggle('on', x === el));
