});

function add(cls, html, tag) {
  const d = document.createElement('div');
  d.className = 'msg ' + cls;
  d.innerHTML = (tag ? '<span class="tag">' + tag + '</span>' : '') + html;
  $('#log').appendChild(d);
  d.scrollIntoView({ behavior: 'smooth', block: 'end' });
  return d;
}

async function ask(text) {
  if (!text.trim()) return;
  add('q', esc(text), '我');
  const box = add('', '查询中…', '助手');
  $('#go').disabled = true;
  try {
    const r = await fetch('/api/ask?q=' + encodeURIComponent(text));
    const j = await r.json();
    box.innerHTML = '<span class="tag">助手</span>' + fmt(j.answer || '没查到');
  } catch (e) {
    box.innerHTML = '<span class="tag">助手</span>请求失败：' + esc(e);
  } finally {
    $('#go').disabled = false;
    $('#q').value = '';
  }
}

$('#go').onclick = () => ask($('#q').value);
$('#q').addEventListener('keydown', e => { if (e.key === 'Enter') ask($('#q').value); });
document.querySelectorAll('.chip').forEach(c => c.onclick = () => ask(c.textContent));

loadDash();
</script>
</body>
</html>
"""


def lan_ip() -> str:
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("223.5.5.5", 80))
        ip = s.getsockname()[0]
        s.close()
        return ip
    except Exception:  # noqa: BLE001
        return "127.0.0.1"


class Handler(BaseHTTPRequestHandler):
    server_version = "BBQBot/1.1"

    def log_message(self, fmt, *args):  # noqa: A003
        sys.stdout.write("  %s %s\n" % (self.address_string(), fmt % args))

    def _json(self, obj) -> None:
        body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):  # noqa: N802
        parsed = urllib.parse.urlparse(self.path)
        path, query = parsed.path, urllib.parse.parse_qs(parsed.query)

        if path == "/":
            body = PAGE.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return

        if path == "/api/dashboard":
            rng = (query.get("range") or ["yesterday"])[0]
            try:
                self._json(dashboard.payload(rng))
            except Exception as exc:  # noqa: BLE001
                self._json({"error": f"{type(exc).__name__}: {exc}"})
            return

        if path == "/api/ask":
            q = (query.get("q") or [""])[0]
            try:
                ans = bot_core.answer(q)
            except Exception as exc:  # noqa: BLE001
                ans = f"查询出错：{type(exc).__name__}: {exc}"
            self._json({"answer": ans})
            return

        if path == "/api/report":
            day = (query.get("date") or [(date.today() - timedelta(days=1)).isoformat()])[0]
            try:
                md = report_mod.build(day)
            except Exception as exc:  # noqa: BLE001
                md = f"生成失败：{exc}"
            self._json({"markdown": md})
            return

        if path == "/api/health":
            self._json({"ok": True})
            return

        self.send_response(404)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.end_headers()
        self.wfile.write(b"not found")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--host", default="0.0.0.0")
    ap.add_argument("--port", type=int, default=8000)
    args = ap.parse_args()

    ip = lan_ip()
    print("=" * 52)
    print("兵哥烧烤 · 经营数据助手已启动")
    print(f"  本机访问： http://127.0.0.1:{args.port}")
    print(f"  手机访问： http://{ip}:{args.port}   （同一个 WiFi）")
    print("  按 Ctrl+C 停止")
    print("=" * 52)

    server = ThreadingHTTPServer((args.host, args.port), Handler)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\n已停止")
    finally:
        server.server_close()
    return 0


if __name__ == "__main__":
    sys.exit(main())
