from __future__ import annotations

import json
import re
import sys
import time
from pathlib import Path

from playwright.sync_api import sync_playwright

sys.stdout.reconfigure(encoding="utf-8", errors="replace")

CDP = "http://127.0.0.1:9222"
OUT = Path(__file__).with_name("data") / "spy"


def main() -> int:
    recs: list[dict] = []
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(CDP, timeout=60000)
        ctx = b.contexts[0]
        pages = [x for x in ctx.pages if "e.waimai.meituan.com" in x.url]
        pg = pages[-1] if pages else ctx.new_page()
        pg.on("response", lambda r: recs.append({
            "url": r.url, "status": r.status,
            "post": (r.request.post_data or "")[:2000],
        }) if r.request.resource_type in ("xhr", "fetch") else None)

        pg.goto("https://e.waimai.meituan.com/", wait_until="domcontentloaded", timeout=45000)
        pg.wait_for_timeout(8000)

        box = pg.evaluate("""() => { const el = document.querySelector('#经营分析');
            if (!el) return null; const r = el.getBoundingClientRect();
            return {x: r.x + r.width/2, y: r.y + r.height/2}; }""")
        print("menu:", box)
        if not box:
            b.close()
            return 1
        pg.mouse.move(box["x"], box["y"])
        pg.wait_for_timeout(1500)

        subs = pg.evaluate("""() => Array.from(document.querySelectorAll('.sub-menu-item_12D-nq, .sub-menus div[id]'))
            .map(e => ({id: e.id || '', text: (e.innerText || '').trim()}))""")
        print("submenus:", json.dumps(subs, ensure_ascii=False)[:600])

        target = None
        for s in subs:
            if "经营数据" in s["text"] or "经营数据" in s.get("id", ""):
                target = s
                break
        if not target:
            print("没找到经营数据子菜单")
            b.close()
            return 1
        print("target:", target)
        rect = pg.evaluate("""(id) => {
            const el = id ? document.getElementById(id) : null;
            const node = el || Array.from(document.querySelectorAll('.sub-menu-item_12D-nq'))
                .find(e => (e.innerText || '').includes('经营数据'));
            if (!node) return null;
            const r = node.getBoundingClientRect();
            return {x: r.x + r.width/2, y: r.y + r.height/2};
        }""", target["id"])
        print("rect:", rect)
        if rect:
            pg.mouse.click(rect["x"], rect["y"])
            pg.wait_for_timeout(12000)

        print("url:", pg.url)
        for f in pg.frames:
            try:
                t = f.inner_text("body")[:150].replace("\n", " | ")
            except Exception:
                t = ""
            print("frame:", f.url[:120], "|", t[:100])

        summary: dict[str, int] = {}
        for r in recs:
            k = re.sub(r"\?.*$", "", r["url"])
            summary[k] = summary.get(k, 0) + 1
        print("\nAPIs:")
        for k, v in sorted(summary.items(), key=lambda kv: -kv[1])[:30]:
            print(f"  {v:3d}  {k[:115]}")

        OUT.mkdir(parents=True, exist_ok=True)
        (OUT / "mt_bizdata.json").write_text(
            json.dumps(recs, ensure_ascii=False, indent=1), encoding="utf-8")
        print("saved ->", OUT / "mt_bizdata.json")
        b.close()
    return 0


if __name__ == "__main__":
    sys.exit(main())
