       "?acctId={acct}&wmPoiId={poi}&durationType={dt}&tabType=3&circleType=0"
       "&bizLineType=0&compareType=0")


def ensure_table() -> None:
    conn = sqlite3.connect(DB)
    conn.execute(
        """CREATE TABLE IF NOT EXISTS mt_flow (
             period TEXT PRIMARY KEY, expose_uv INTEGER, click_uv INTEGER, order_uv INTEGER,
             click_rate REAL, order_rate REAL, fetched_at TEXT)"""
    )
    conn.commit()
    conn.close()


def open_bizdata(page) -> None:
    """从美团后台导航进「经营分析 → 经营数据」。"""
    page.goto("https://e.waimai.meituan.com/", wait_until="domcontentloaded", timeout=45000)
    page.wait_for_timeout(7000)
    box = page.evaluate(
        """() => { const el = document.querySelector('#经营分析');
            if (!el) return null; const r = el.getBoundingClientRect();
            return {x: r.x + r.width / 2, y: r.y + r.height / 2}; }"""
    )
    if not box:
        raise RuntimeError("找不到经营分析菜单")
    page.mouse.move(box["x"], box["y"])
    page.wait_for_timeout(700)
    page.mouse.click(box["x"], box["y"])
    page.wait_for_timeout(1800)
    item = page.evaluate(
        """() => {
            const n = Array.from(document.querySelectorAll('*')).filter(e =>
                e.children.length === 0 && (e.textContent || '').trim() === '经营数据');
            if (!n.length) return null;
            const r = n[n.length - 1].getBoundingClientRect();
            return {x: r.x + r.width / 2, y: r.y + r.height / 2};
        }"""
    )
    if not item:
        raise RuntimeError("找不到经营数据子菜单")
    page.mouse.click(item["x"], item["y"])
    page.wait_for_timeout(9000)


def biz_frame(page):
    return next((f for f in page.frames
                 if "waimaieapp.meituan.com" in f.url and f != page.main_frame), None)


def fetch_period(frame, dt: int) -> dict:
    res = frame.evaluate(
        """async (url) => {
            const r = await fetch(url, {credentials: "include"});
            return {status: r.status, text: await r.text()};
        }""",
        API.format(acct=ACCT_ID, poi=POI_ID, dt=dt),
    )
    if res["status"] != 200:
        raise RuntimeError(f"HTTP {res['status']}")
    payload = json.loads(res["text"])
    if payload.get("code") != 0:
        raise RuntimeError(payload.get("msg", "接口返回异常"))
    out = {}
    for item in payload.get("data", []):
        field = item.get("field")
        base = item.get("base")
        if field == "exposeUv":
            out["expose_uv"] = int(base or 0)
        elif field == "clickUv":
            out["click_uv"] = int(base or 0)
        elif field == "orderUv":
            out["order_uv"] = int(base or 0)
        elif field == "clickRate":
            out["click_rate"] = float(base or 0)
        elif field == "orderRate":
            out["order_rate"] = float(base or 0)
    return out


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--dry", action="store_true")
    args = ap.parse_args()

    ensure_table()
    results: dict[str, dict] = {}
    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(CDP, timeout=60000)
        ctx = b.contexts[0]
        pages = [x for x in ctx.pages if "e.waimai.meituan.com" in x.url]
        page = pages[-1] if pages else ctx.new_page()
        open_bizdata(page)
        frame = biz_frame(page)
        if not frame:
            print("没找到经营数据 iframe")
            b.close()
            return 1
        for dt, key in PERIODS.items():
            try:
                data = fetch_period(frame, dt)
                results[key] = data
                print(f"{key}: {data}")
            except Exception as exc:  # noqa: BLE001
                print(f"{key}: 失败 {type(exc).__name__}: {exc}")
        b.close()

    if args.dry or not results:
        return 0

    now = datetime.now().isoformat(timespec="seconds")
    conn = sqlite3.connect(DB)
    for key, d in results.items():
        conn.execute(
            """INSERT INTO mt_flow (period, expose_uv, click_uv, order_uv, click_rate, order_rate, fetched_at)
               VALUES (?,?,?,?,?,?,?)
               ON CONFLICT(period) DO UPDATE SET
                 expose_uv=excluded.expose_uv, click_uv=excluded.click_uv, order_uv=excluded.order_uv,
                 click_rate=excluded.click_rate, order_rate=excluded.order_rate,
                 fetched_at=excluded.fetched_at""",
            (key, d.get("expose_uv", 0), d.get("click_uv", 0), d.get("order_uv", 0),
             d.get("click_rate", 0), d.get("order_rate", 0), now),
        )
    conn.commit()
    conn.close()
    print("已写入 mt_flow")
    return 0


if __name__ == "__main__":
    sys.exit(main())
