import io
p = "refresh.py"
s = io.open(p, encoding="utf-8").read()
s = s.replace('''def main() -> int:
    if not browser_alive():
        print("浏览器未运行，跳过本次刷新")
        return 0''','''def start_browser() -> bool:
    subprocess.run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass",
                    "-File", str(HERE / "start-browser.ps1"), "-Silent"], check=False)
    for _ in range(20):
        if browser_alive():
            return True
        time.sleep(2)
    return False


def stop_browser() -> None:
    subprocess.run(["powershell", "-NoProfile", "-Command",
                    "Get-CimInstance Win32_Process -Filter \\"Name='msedge.exe'\\" | "
                    "Where-Object { $_.CommandLine -like '*edge-profile*' } | "
                    "ForEach-Object { Stop-Process -Id $_.ProcessId -Force }"], check=False)


def main() -> int:
    started = False
    if not browser_alive():
        print("浏览器未运行，启动中…")
        started = start_browser()
        if not started:
            print("启动失败，跳过本次刷新")
            return 0''')
s = s.replace('''    run("ele_promo.py")
    return 0''','''    run("ele_promo.py")
    if started:
        stop_browser()
        print("已关闭临时浏览器")
    return 0''')
io.open(p, "w", encoding="utf-8").write(s)
print("refresh.py 支持自动起停浏览器")
