{"command": "cd "C:\Users\24380\Documents\deepseek-harness\default-workspace\meituan-agent"
$py = "C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe"
$env:PYTHONIOENCODING = "utf-8"
@'
from playwright.sync_api import sync_playwright
import sys
sys.stdout.reconfigure(encoding="utf-8", errors="replace")
TARGET = "2026-11-09"
with sync_playwright() as p:
    b = p.chromium.connect_over_cdp("http://127.0.0.1:9222", timeout=60000)
    pg = [x for x in b.contexts[0].pages if "melody.shop.ele.me" in x.url][-1]
    pg.goto("https://melody.shop.ele.me/app/shop/546266599/downloadCenter#app.shop.downloadCenter", wait_until="domcontentloaded", timeout=45000)
    pg.wait_for_timeout(9000)
    fr = next((f for f in pg.frames if "download-center" in f.url), None)
    for t in ("报表下载", "商品下载", "套餐子品"):
        fr.evaluate("""(t) => { const n = Array.from(document.querySelectorAll('div,span')).filter(e => e.children.length===0 && (e.textContent||'').trim()===t); if(n.length) n[n.length-1].click(); }""", t)
        pg.wait_for_timeout(1500)
    before = fr.evaluate("""() => Array.from(document.querySelectorAll('input')).map(i => ({ph:i.placeholder||'', v:i.value||'', ro:i.readOnly}))""")
    print("inputs before:", before)
    res = fr.evaluate("""(day) => {
        const inputs = Array.from(document.querySelectorAll('input')).filter(i => (i.placeholder||'').includes('日期') || (i.value||'').match(/^\\d{4}-\\d{2}-\\d{2}$/));
        if (!inputs.length) return 'no-input';
        for (const el of inputs) {
            const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
            setter.call(el, day);
            el.dispatchEvent(new Event('input', {bubbles: true}));
            el.dispatchEvent(new Event('change', {bubbles: true}));
            el.dispatchEvent(new Event('blur', {bubbles: true}));
        }
        return 'set:' + inputs.length;
    }""", TARGET)
    print("注入日期:", res)
    pg.wait_for_timeout(2500)
    after = fr.evaluate("""() => Array.from(document.querySelectorAll('input')).map(i => ({ph:i.placeholder||'', v:i.value||''})).filter(x => x.v)""")
    print("inputs after:", after)
    print("页面:", fr.inner_text("body")[:200].replace("\n"," | "))
    b.close()
