@'
from playwright.sync_api import sync_playwright
import sys, json
sys.stdout.reconfigure(encoding="utf-8", errors="replace")
JS = """
async (qs) => {
  const url = "/gw/bizdata/flow/single/overview/tab?" + qs;
  const r = await fetch(url, {credentials: "include"});
  const t = await r.text();
  try {
    const j = JSON.parse(t);
    if (j.code !== 0) return {code: j.code, msg: j.msg};
    const pick = {};
    for (const it of j.data || []) {
      if (["exposeUv","clickUv","orderUv"].includes(it.field)) pick[it.field] = it.base;
    }
    return {code: 0, ...pick};
  } catch (e) { return {raw: t.slice(0,120)}; }
}
"""
with sync_playwright() as p:
    b = p.chromium.connect_over_cdp("http://127.0.0.1:9222", timeout=60000)
    pg = [x for x in b.contexts[0].pages if "e.waimai.meituan.com" in x.url][-1]
    # 进入经营数据
    pg.goto("https://e.waimai.meituan.com/", wait_until="domcontentloaded", timeout=45000)
    pg.wait_for_timeout(7000)
    box = pg.evaluate("""() => { const el = document.querySelector('#经营分析'); const r=el.getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; }""")
    pg.mouse.move(box["x"], box["y"]); pg.wait_for_timeout(600); pg.mouse.click(box["x"], box["y"]); pg.wait_for_timeout(1800)
    item = pg.evaluate("""() => { const n = Array.from(document.querySelectorAll('*')).filter(e => e.children.length===0 && (e.textContent||'').trim()==='经营数据'); if(!n.length) return null; const r=n[n.length-1].getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; }""")
    if item:
        pg.mouse.click(item["x"], item["y"]); pg.wait_for_timeout(9000)
    fr = next((f for f in pg.frames if "waimaieapp.meituan.com" in f.url and f != pg.main_frame), None)
    print("frame:", fr.url[:80] if fr else None)
    base = "acctId=78953776&wmPoiId=35053443&tabType=3&circleType=0&bizLineType=0&compareType=0"
    for dt in (0,1,2,3,4,5):
        for day in ("", "20261109"):
            qs = f"{base}&durationType={dt}&dt={day}"
            r = fr.evaluate(JS, qs)
            print(f"durationType={dt} dt={day or '-':<9} -> {r}")
    b.close()
'@ | Set-Content probe_flow_custom.py -Encoding utf8
& $py probe_flow_custom.py 2>&1 | Select-Object -Last 16", "description": "Probe meituan flow API for custom date support", "timeoutMs": 400000}

