def frame_offset(frame, page) -> tuple[float, float]:
    """该 iframe 在主页面的位置（把 frame 内坐标换算成鼠标坐标）。"""
    try:
        el = page.evaluate(
            """() => {
                const f = Array.from(document.querySelectorAll('iframe'))
                    .find(x => (x.src || '').includes('business-analysis'));
                if (!f) return null;
                const r = f.getBoundingClientRect();
                return {x: r.x, y: r.y};
            }"""
        )
        if el:
            return float(el["x"]), float(el["y"])
    except Exception:  # noqa: BLE001
        pass
    return 0.0, 0.0


def click_in_frame(frame, page, locator, label: str = "") -> bool:
    """优先真实鼠标点击（对自绘/弹层组件更稳），失败退回 locator.click。"""
    try:
        box = locator.first.bounding_box()
    except Exception:  # noqa: BLE001
        box = None
    if box and box.get("width"):
        try:
            ox, oy = frame_offset(frame, page)
            mx = box["x"] + box["width"] / 2 + ox
            my = box["y"] + box["height"] / 2 + oy
            page.mouse.move(mx - 6, my - 4)
            time.sleep(random.uniform(0.12, 0.3))
            page.mouse.move(mx, my)
            time.sleep(random.uniform(0.1, 0.22))
            page.mouse.click(mx, my)
            return True
        except Exception:  # noqa: BLE001
            pass
    try:
        locator.first.click(timeout=5000)
        return True
    except Exception as exc:  # noqa: BLE001
        print(f"    点击{label}失败: {type(exc).__name__}")
        return False


def selected_text(frame) -> str:
    try:
        t = re.sub(r"\s+", " ", frame.inner_text("body"))
    except Exception:  # noqa: BLE001
        return ""
    m = re.search(r"已选时间：([^|]{0,40})", t)
    return m.group(1).strip() if m else ""


def open_picker(frame, page) -> bool:
    """确保日历弹层打开。"""
    if frame.locator("td[title]").count() > 0:
        return True
    for sel in (".ant-picker-range", ".ant-picker", "input[placeholder*='开始']"):
        loc = frame.locator(sel)
        if loc.count() == 0:
            continue
        if click_in_frame(frame, page, loc, "日期控件"):
            time.sleep(1.6)
            if frame.locator("td[title]").count() > 0:
