'''    <div class="grid" id="grid"></div>
    <div class="tl-wrap" id="tlWrap" style="display:none">
      <div class="tl-title">晚间 17:00 – 24:00</div>
      <div id="tlEvening"></div>
      <div class="tl-title">凌晨 00:00 – 05:00</div>
      <div id="tlLate"></div>
    </div>''')

s = s.replace('''  .cov { font-size:11px;''',
'''  .tl-wrap { margin-top:14px; }
  .tl-title { font-size:12px; color:#6b7178; font-weight:600; margin:12px 2px 6px; }
  .tl-svg { width:100%; height:86px; display:block; }
  .cov { font-size:11px;''')

# 渲染函数
js = """
function renderTimeline(j) {
  const wrap = document.getElementById('tlWrap');
  const tl = j.timeline;
  if (!tl || (!tl.evening?.length && !tl.late?.length)) { wrap.style.display = 'none'; return; }
  wrap.style.display = 'block';
  drawTimeline('tlEvening', tl.evening || [], 17, 24, '#ff6a00');
  drawTimeline('tlLate', tl.late || [], 0, 5, '#7c5cff');
}

function drawTimeline(elId, points, h0, h1, color) {
  const host = document.getElementById(elId);
  const W = host.clientWidth || 340, H = 86, pad = 10;
  const innerW = W - pad * 2;
  const maxA = Math.max(30, ...points.map(p => p.a));
  const baseY = H - 18;
  const scaleX = t => {
    const [hh, mm] = t.split(':').map(Number);
    const frac = (hh - h0) + (h1 === 24 && hh < h0 ? 24 : 0) / 1 + mm / 60;
    const rel = ((hh - h0) + mm / 60) / (h1 - h0);
    return pad + Math.max(0, Math.min(1, rel)) * innerW;
  };
  const scaleY = a => baseY - Math.min(1, a / maxA) * (baseY - 18);
  let svg = `<svg class="tl-svg" viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg">`;
  svg += `<line x1="${pad}" y1="${baseY}" x2="${W - pad}" y2="${baseY}" stroke="#e3e5e8" stroke-width="1"/>`;
  for (let h = h0; h <= h1; h++) {
    const x = pad + ((h - h0) / (h1 - h0)) * innerW;
    svg += `<line x1="${x}" y1="${baseY}" x2="${x}" y2="${baseY + 4}" stroke="#cfd3d8"/>`;
    if (h % (h1 - h0 > 7 ? 1 : 1) === 0)
      svg += `<text x="${x}" y="${H - 4}" font-size="9" fill="#9aa1a9" text-anchor="middle">${h}</text>`;
  }
  for (const p of points) {
    const x = scaleX(p.t), y = scaleY(p.a);
    svg += `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="3.4" fill="${color}" fill-opacity="0.75">`
        + `<title>${p.t}  ¥${p.a.toFixed(2)}</title></circle>`;
  }
  const big = points.slice().sort((a, b) => b.a - a.a).slice(0, 3);
  for (const p of big) {
    const x = scaleX(p.t), y = scaleY(p.a);
    svg += `<text x="${x.toFixed(1)}" y="${(y - 7).toFixed(1)}" font-size="9" fill="#5a6169" text-anchor="middle">${p.a.toFixed(0)}</text>`;
  }
  svg += '</svg>';
  host.innerHTML = svg;
}
"""
s = s.replace("async function load() {", js + "\nasync function load() {")
s = s.replace('''  render();''', '''  render();
  renderTimeline(j);''')
io.open(p, "w", encoding="utf-8").write(s)
print("时间线渲染已加")
