@'
import urllib.request, json
d = json.load(urllib.request.urlopen("http://127.0.0.1:8000/api/dashboard?range=yesterday&platform=all"))
print("美团晚间:", len((d.get("timeline") or {}).get("evening", [])), "凌晨:", len((d.get("timeline") or {}).get("late", [])))
print("闪购晚间:", len((d.get("timeline_eleme") or {}).get("evening", [])), "凌晨:", len((d.get("timeline_eleme") or {}).get("late", [])))
'@ | Set-Content scripts\verify_tl2.py -Encoding utf8
& $py scripts\verify_tl2.py", "description": "Build dual timelines UI and verify data counts", "timeoutMs": 240000}

