@'
import io
p = "web_app.py"
s = io.open(p, encoding="utf-8").read()

js = '''function renderTimeline(j) {
  const wrap = document.getElementById('tlWrap');
  if (!wrap) return;
  const mt = j.timeline || {}, ele = j.timeline_eleme || {};
  const isTimeTab = (state.tab === 'time');
  if (!isTimeTab) { wrap.style.display = 'none'; return; }
  wrap.style.display = 'block';
  drawTimeline('tlMtEvening', mt.evening || [], 17, 24, '#ff6a00');
  drawTimeline('tlMtLate', mt.late || [], 0, 5, '#ff6a00');
  drawTimeline('tlEleEvening', ele.evening || [], 17, 24, '#7c5cff');
  drawTimeline('tlEleLate', ele.late || [], 0, 5, '#7c5cff');
}

function drawTimeline(elId, points, h0, h1, color) {
  const host = document.getElementById(elId);
  if (!host) return;
  if (!points.length) { host.innerHTML = '<div class="tl-empty">该时段暂无订单</div>'; return; }
  const W = host.clientWidth || 340, H = 90, pad = 12;
  const innerW = W - pad * 2;
  const maxA = Math.max(30, ...points.map(p => p.a));
  const baseY = H - 18;
  const xOf = t => {
    const [hh, mm] = t.split(':').map(Number);
    const rel = ((hh - h0) + mm / 60) / (h1 - h0);
    return pad + Math.max(0, Math.min(1, rel)) * innerW;
  };
  const yOf = a => baseY - Math.min(1, a / maxA) * (baseY - 20);
  let svg = `<svg class="tl-svg" viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg">`;
  svg += `<line x1="${pad}" y1="${baseY}" x2="${W - pad}" y2="${baseY}" stroke="#e3e5e8"/>`;
  for (let h = h0; h <= h1; h++) {
    const x = pad + ((h - h0) / (h1 - h0)) * innerW;
    svg += `<line x1="${x}" y1="${baseY}" x2="${x}" y2="${baseY + 4}" stroke="#cfd3d8"/>`;
    svg += `<text x="${x}" y="${H - 4}" font-size="9" fill="#9aa1a9" text-anchor="middle">${h}</text>`;
  }
  for (const p of points) {
    const x = xOf(p.t), y = yOf(p.a);
    svg += `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="3.6" fill="${color}" fill-opacity="0.72">`
        + `<title>${p.t}  ¥${p.a.toFixed(2)}</title></circle>`;
  }
  const big = points.slice().sort((a, b) => b.a - a.a).slice(0, 3);
  for (const p of big) {
    const x = xOf(p.t), y = yOf(p.a);
    svg += `<text x="${x.toFixed(1)}" y="${(y - 8).toFixed(1)}" font-size="9" fill="#5a6169" text-anchor="middle">¥${p.a.toFixed(0)}</text>`;
  }
  svg += '</svg>';
  host.innerHTML = svg;
}

'''
s = s.replace("async function loadDash() {", js + "async function loadDash() {", 1)
s = s.replace('''      render(window.__dash);
    };
  });
  render(j);
}''','''      render(window.__dash);
      renderTimeline(window.__dash);
    };
  });
  render(j);
  renderTimeline(j);
}''')
io.open(p, "w", encoding="utf-8").write(s)
print("时间线 JS 已注入 loadDash")
