Start-Sleep -Seconds 4
@'
from playwright.sync_api import sync_playwright
import pathlib
out = pathlib.Path("data/screenshots")
with sync_playwright() as p:
    b = p.chromium.launch(channel="msedge", headless=True)
    pg = b.new_page(viewport={"width": 414, "height": 1200}, device_scale_factor=2)
    pg.goto("http://127.0.0.1:8000/", wait_until="networkidle", timeout=20000)
    for plat, name in (("meituan","mt"), ("eleme","ele"), ("all","all")):
        pg.click(f"#plats .plat[data-k='{plat}']"); pg.wait_for_timeout(900)
        pg.click("#ranges .range[data-k='7d']"); pg.wait_for_timeout(900)
        pg.click("#tabs .tab[data-k='time']"); pg.wait_for_timeout(900)
        secs = pg.evaluate("""() => ({
            mt: getComputedStyle(document.getElementById('tlSecMt')).display,
            ele: getComputedStyle(document.getElementById('tlSecEle')).display,
            svg: document.querySelectorAll('.tl-svg').length
        })""")
        print(plat, secs)
        pg.screenshot(path=str(out / f"final_13_time_{name}.png"), full_page=True)
    b.close()
