    for _ in range(3):
        click_text("报表下载"); pg.wait_for_timeout(1500)
        click_text("订单下载"); pg.wait_for_timeout(2500)
        if "下单时间" in fr.inner_text("body"): break
    info = fr.evaluate("""() => {
        const all = Array.from(document.querySelectorAll('*'));
        const hit = all.find(e => (e.textContent||'').trim().startsWith('日期选项'));
        const radios = Array.from(document.querySelectorAll('.ant-radio-wrapper, label')).map(l => ({
            t: (l.innerText||'').trim().slice(0,14),
            cls: (l.className||'').toString().slice(0,40),
            checked: !!l.querySelector('input:checked') || (l.className||'').includes('checked')
        })).filter(x => x.t.includes('日期'));
        return {anchor: hit ? hit.tagName + '.' + (hit.className||'').toString().slice(0,30) : null, radios};
    }""")
    print(json.dumps(info, ensure_ascii=False, indent=1)[:900])
    b.close()
