  const xOf = t => {
    const [hh, mm] = t.split(':').map(Number);
    const rel = ((hh - h0) + mm / 60) / (h1 - h0);
    return padL + Math.max(0, Math.min(1, rel)) * innerW;
  };
  const yOf = a => baseY - Math.min(1, a / maxA) * 52;

  let svg = `<svg class="tl-svg" style="height:${H}px" viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg">`;
  svg += `<line x1="${padL}" y1="${baseY}" x2="${W - padR}" y2="${baseY}" stroke="#e3e5e8"/>`;
  for (let h = h0; h <= h1; h++) {
    const x = padL + ((h - h0) / (h1 - h0)) * innerW;
    svg += `<line x1="${x}" y1="${baseY}" x2="${x}" y2="${baseY + 4}" stroke="#cfd3d8"/>`;
    svg += `<text x="${x}" y="${baseY + 15}" font-size="9" fill="#9aa1a9" text-anchor="middle">${h}</text>`;
  }

  const sorted = points.slice().sort((a, b) => a.t.localeCompare(b.t));
  sorted.forEach((p, i) => {
    const x = xOf(p.t), y = yOf(p.a);
    const lvl = i % 3;                    // 三档错开，减少重叠
    const ty = Math.max(12, y - 9 - lvl * 11);
    svg += `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="3.2" fill="${color}">`
        + `<title>${p.t}  ¥${p.a.toFixed(2)}</title></circle>`;
    svg += `<line x1="${x.toFixed(1)}" y1="${(y - 3).toFixed(1)}" x2="${x.toFixed(1)}" y2="${ty + 2}" stroke="${color}" stroke-opacity="0.28" stroke-width="0.7"/>`;
    svg += `<text x="${x.toFixed(1)}" y="${ty}" font-size="8" fill="#6b7178" text-anchor="middle">${p.t}</text>`;
    svg += `<text x="${x.toFixed(1)}" y="${ty - 8}" font-size="8" fill="${color}" text-anchor="middle">¥${p.a.toFixed(0)}</text>`;
  });
  svg += '</svg>';
  host.innerHTML = svg;
}

