{"command": "cd "C:\Users\24380\Documents\deepseek-harness\default-workspace\meituan-agent"
$py = "C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe"
$env:PYTHONIOENCODING = "utf-8"
@'
import io
p = "dashboard.py"
s = io.open(p, encoding="utf-8").read()

fn = '''

FOOD_NOISE = ["碳烤", "炭烤", "烤", "小串", "大串", "串", "（", "）", "(", ")", "·", "｜", "|", " "]


def _norm_name(name: str) -> str:
    s = str(name or "").strip()
    for w in FOOD_NOISE:
        s = s.replace(w, "")
    return re.sub(r"[^\\u4e00-\\u9fffA-Za-z0-9]", "", s)


def _menu_map(c) -> dict[str, int]:
    out = {}
    try:
        for r in c.execute("SELECT name_norm, cost_cents FROM menu_cost"):
            if r["name_norm"]:
                out[r["name_norm"]] = r["cost_cents"] or 0
    except Exception:  # noqa: BLE001
        pass
    return out


def _cost_of(name: str, menu: dict[str, int]) -> int | None:
    n = _norm_name(name)
    if not n:
        return None
    if n in menu:
        return menu[n]
    best, best_score = None, 0.0
    for k, v in menu.items():
        if not k:
            continue
        if n in k or k in n:
            score = min(len(n), len(k)) / max(len(n), len(k))
            if score > best_score:
                best, best_score = v, score
    if best is not None and best_score >= 0.5:
        return best
    # 字符重合度兜底
    for k, v in menu.items():
        common = len(set(n) & set(k))
        if common >= 3:
            score = common / max(len(set(n)), len(set(k)))
            if score > best_score and score >= 0.75:
                best, best_score = v, score
    return best


def _food_cost(c, start: str, end: str, platform: str) -> dict:
    """按菜单成本 × 销量算食材成本，返回 {cost, matched_qty, total_qty, unmatched}。"""
    menu = _menu_map(c)
    if not menu:
        return {"cost": None, "matched_qty": 0, "total_qty": 0, "unmatched": []}

    items: list[tuple[str, float]] = []
    if platform == "meituan":
        try:
            for r in c.execute(
                """SELECT sku_name, SUM(qty) q FROM order_items
                   WHERE is_combo_parent = 0
                     AND order_no IN (SELECT order_no FROM orders
                                      WHERE date(created_at) BETWEEN ? AND ?
                                        AND status NOT LIKE '%取消%')
                   GROUP BY sku_name""",
                (start, end),
            ):
                items.append((r["sku_name"], r["q"] or 0))
        except Exception:  # noqa: BLE001
            pass
    else:
        try:
            for r in c.execute("SELECT item_name, SUM(qty) q FROM ele_goods GROUP BY item_name"):
                if "【" in (r["item_name"] or ""):
                    continue
                items.append((r["item_name"], r["q"] or 0))
            for r in c.execute(
                """SELECT sub_name, SUM(qty) q FROM ele_combo_items
                   WHERE date BETWEEN ? AND ? GROUP BY sub_name""", (start, end)):
                items.append((r["sub_name"], r["q"] or 0))
        except Exception:  # noqa: BLE001
            pass

    total = sum(q for _, q in items) or 0
    cost = 0
    matched = 0
    unmatched: list[str] = []
    for name, q in items:
        unit = _cost_of(name, menu)
        if unit is None:
            if q:
                unmatched.append(f"{name}×{q:.0f}")
            continue
        cost += unit * q
        matched += q
    return {"cost": cost, "matched_qty": matched, "total_qty": total, "unmatched": unmatched}

'''
s = s.replace("def _profit_stats(", fn + "def _profit_stats(", 1)
io.open(p, "w", encoding="utf-8").write(s)
print("食材成本函数已加")
