with sync_playwright() as p:
    b = p.chromium.connect_over_cdp("http://127.0.0.1:9222", timeout=60000)
    ctx = b.contexts[0]
    pg = [x for x in ctx.pages if "melody.shop.ele.me" in x.url][-1]
    fr = next((f for f in pg.frames if "doujin" in f.url), None)
    print("frame:", fr.url[:80] if fr else None)
    if fr:
        info = fr.evaluate("""() => {
            const hits = Array.from(document.querySelectorAll('*'))
                .filter(e => (e.textContent||'').trim() === '消费记录' && e.children.length === 0);
            return hits.map(e => {
                let a = e.closest('a');
                return {
                    tag: e.tagName,
                    href: a ? a.getAttribute('href') : null,
                    onclick: (e.getAttribute('onclick')||''),
                    cls: (e.className||'').toString().slice(0,40),
                    parentTag: e.parentElement ? e.parentElement.tagName : null,
                    parentHref: e.parentElement && e.parentElement.closest('a') ? e.parentElement.closest('a').getAttribute('href') : null
                };
            });
        }""")
        print(json.dumps(info, ensure_ascii=False, indent=1)[:800])
        # 也看 iframe 是否被包在 a 里
        anchors = fr.evaluate("""() => Array.from(document.querySelectorAll('a')).map(a => a.getAttribute('href')).filter(Boolean).slice(0,10)""")
        print("页面内链接:", anchors)
    b.close()
