HOME = "https://melody.shop.ele.me/app/shop/546266599/#app.shop.dashboard"
SHOP_ID = 546266599

JS = """
async ({begin, end, offset, limit}) => {
    const body = {
        service: "OrderWebService", method: "queryAllOrders",
        params: {shopId: %d,
                 condition: {offset, limit, beginTime: begin, endTime: end},
                 allOrderQueryType: "FINISHED"},
        id: "dsh-" + Date.now() + "-" + offset,
        metas: {appVersion: "1.0.0", appName: "melody",
                ksid: localStorage.getItem("ksid") || "", shopId: %d},
        ncp: "2.0.0"
    };
    const r = await fetch("https://app-api.shop.ele.me/fulfill/weborder/queryAllOrders/",
        {method: "POST", headers: {"content-type": "application/json"},
         credentials: "include", body: JSON.stringify(body)});
    const t = await r.text();
    if (r.status !== 200) return {status: r.status, text: t.slice(0, 200)};
    try {
        const j = JSON.parse(t);
        const list = (j.result && j.result.orders) || [];
        return {status: 200, orders: list};
    } catch (e) {
        return {status: r.status, text: t.slice(0, 200)};
    }
}
""" % (SHOP_ID, SHOP_ID)


def ensure_tables() -> None:
    conn = sqlite3.connect(DB)
    conn.execute(
        """CREATE TABLE IF NOT EXISTS ele_orders (
             order_no TEXT PRIMARY KEY, date TEXT, hhmm TEXT, amount_cents INTEGER,
             status TEXT, fetched_at TEXT)"""
    )
    conn.execute(
        """CREATE TABLE IF NOT EXISTS ele_order_items (
             order_no TEXT, date TEXT, item_name TEXT, qty REAL, is_combo INTEGER,
             fetched_at TEXT, PRIMARY KEY (order_no, item_name, is_combo))"""
    )
    conn.commit()
    conn.close()


def money_cents(order: dict) -> int:
    """尽量从订单里找出顾客实付。"""
    cands = []
    for path in (("settlementInfo", "totalPrice"), ("settlementInfo", "actualPay"),
                 ("settlementInfo", "shopIncome"), ("header", "totalPrice"),
                 ("header", "orderPrice"), ("totalPrice",), ("payPrice",)):
        cur = order
        ok = True
        for key in path:
            if isinstance(cur, dict) and key in cur:
                cur = cur[key]
            else:
                ok = False
                break
        if ok and isinstance(cur, (int, float)):
            cands.append(float(cur))
    return int(round((cands[0] if cands else 0) * 100))


def parse_order(o: dict) -> tuple[dict, list[dict]]:
    no = str(o.get("id") or "")
    t = str(o.get("activeTime") or "")
    day = t[:10]
    hhmm = t[11:16]
    status = str(o.get("status") or "")
    cents = money_cents(o)

    items: list[dict] = []
    food = o.get("foodInfo") or {}
    for g in food.get("groups") or []:
        for it in g.get("items") or []:
            name = str(it.get("name") or "").strip()
            qty = float(it.get("quantity") or 1)
            if not name:
                continue
            combo_children = it.get("comboItems") or []
            if combo_children:
                for c in combo_children:
                    cn = str(c.get("name") or "").strip()
                    cq = float(c.get("quantity") or 1)
                    if not cn:
                        continue
                    # 套餐子项名可能是 "A+B+C"，拆开
                    for part in cn.split("+"):
                        part = part.strip()
                        if part:
                            items.append({"name": part, "qty": cq * qty, "is_combo": 1})
            else:
                items.append({"name": name, "qty": qty, "is_combo": 0})
    return ({"order_no": no, "date": day, "hhmm": hhmm, "amount_cents": cents,
             "status": status}, items)


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--date")
    ap.add_argument("--days", type=int, default=0)
    args = ap.parse_args()

    if args.date:
        days = [args.date]
    elif args.days:
        today = date.today()
        days = [(today - timedelta(days=i)).isoformat() for i in range(args.days - 1, -1, -1)]
    else:
        ap.error("需要 --date 或 --days")

    ensure_tables()
    conn = sqlite3.connect(DB)
    now = datetime.now().isoformat(timespec="seconds")
    total_orders = 0
    total_items = 0

    with sync_playwright() as p:
        b = p.chromium.connect_over_cdp(CDP, timeout=60000)
        ctx = b.contexts[0]
        pages = [x for x in ctx.pages if "melody.shop.ele.me" in x.url]
        page = pages[-1] if pages else ctx.new_page()
        if "melody.shop.ele.me" not in page.url or "ksid" not in (page.evaluate("() => JSON.stringify(localStorage)") or ""):
            page.goto(HOME, wait_until="domcontentloaded", timeout=45000)
            page.wait_for_timeout(8000)

        ksid = page.evaluate("() => localStorage.getItem('ksid') || ''")
        if not ksid:
            print("没拿到 ksid，先打开一次订单查询页再试")
            b.close()
            return 1

        for day in days:
            begin = f"{day}T00:00:00"
            end = f"{day}T23:59:59"
            offset = 0
            got = 0
            while True:
                res = page.evaluate(JS, {"begin": begin, "end": end, "offset": offset, "limit": 20})
                if res.get("status") != 200:
                    print(f"{day} 请求失败: {res.get('status')} {res.get('text','')[:80]}")
                    break
                orders = res.get("orders") or []
                if not orders:
                    break
                for o in orders:
                    row, items = parse_order(o)
                    if not row["order_no"]:
                        continue
                    conn.execute(
                        """INSERT INTO ele_orders (order_no, date, hhmm, amount_cents, status, fetched_at)
                           VALUES (?,?,?,?,?,?)
                           ON CONFLICT(order_no) DO UPDATE SET
                             date=excluded.date, hhmm=excluded.hhmm,
                             amount_cents=excluded.amount_cents, status=excluded.status,
                             fetched_at=excluded.fetched_at""",
                        (row["order_no"], row["date"], row["hhmm"], row["amount_cents"],
                         row["status"], now),
                    )
                    conn.execute("DELETE FROM ele_order_items WHERE order_no = ?", (row["order_no"],))
                    for it in items:
                        conn.execute(
                            """INSERT OR REPLACE INTO ele_order_items
                                 (order_no, date, item_name, qty, is_combo, fetched_at)
                               VALUES (?,?,?,?,?,?)""",
                            (row["order_no"], row["date"], it["name"], it["qty"],
                             it["is_combo"], now),
                        )
                        total_items += 1
                    total_orders += 1
                    got += 1
                if len(orders) < 20:
                    break
                offset += 20
            print(f"{day}: {got} 单")
            conn.commit()

        b.close()

    conn.close()
    print(f"合计 {total_orders} 单，{total_items} 条明细")
    return 0


if __name__ == "__main__":
    sys.exit(main())
