{"command": "cd "C:\Users\24380\Documents\deepseek-harness\default-workspace\meituan-agent"
$py = "C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe"
$enc = New-Object System.Text.UTF8Encoding($true)
$content = @'
param(
    [switch]$Silent,
    [switch]$Check,
    [int]$Port = 9222
)

$ErrorActionPreference = "SilentlyContinue"
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
$ProfileDir = Join-Path $root "edge-profile"
$edge = "C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe"
if (-not (Test-Path $edge)) { $edge = "C:\Program Files\Microsoft\Edge\Application\msedge.exe" }

if ($Check) {
    try {
        $targets = Invoke-RestMethod "http://127.0.0.1:$Port/json/list" -TimeoutSec 5
        $targets | Where-Object { $_.type -eq "page" } | ForEach-Object { "{0}  {1}" -f $_.title, $_.url }
    } catch {
        "调试端口 $Port 没有响应"
    }
    exit 0
}

$browserArgs = @(
    "--remote-debugging-port=$Port",
    ("--user-data-dir={0}" -f $ProfileDir),
    "--no-first-run",
    "--no-default-browser-check",
    "--disable-gpu",
    "--mute-audio"
)

if ($Silent) {
    # 关键：不用 --headless（无头模式下闪购的子应用会 401），
    # 改成有界面但把窗口放到屏幕外，既不影响使用又能拿到完整数据。
    $browserArgs += @(
        "--window-position=-2400,-2400",
        "--window-size=1440,900"
    )
    $browserArgs += "https://e.waimai.meituan.com/"
} else {
    $browserArgs += @(
        "--window-size=1440,900",
        "https://e.waimai.meituan.com/",
        "https://melody.shop.ele.me/"
    )
}

if ($Silent) {
    Write-Host "以离屏窗口模式启动 Edge（调试端口 $Port）" -ForegroundColor Cyan
} else {
    Write-Host ("启动 Edge，独立配置目录：{0}" -f $ProfileDir) -ForegroundColor Cyan
    Write-Host "在弹出的窗口里登录美团和淘宝闪购后台，完成后回来告诉我。" -ForegroundColor Green
}

# 清理上次异常退出留下的单例锁
Remove-Item (Join-Path $ProfileDir "SingletonLock"), (Join-Path $ProfileDir "SingletonCookie"), (Join-Path $ProfileDir "SingletonSocket") -Force -ErrorAction SilentlyContinue

Start-Process -FilePath $edge -ArgumentList $browserArgs
'@
[System.IO.File]::WriteAllText((Join-Path (Get-Location) "start-browser.ps1"), $content, $enc)
"已重写 start-browser.ps1（静默模式改为离屏窗口）"
Get-CimInstance Win32_Process -Filter "Name='msedge.exe'" | Where-Object { $_.CommandLine -like "*edge-profile*" } | ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }
Start-Sleep -Seconds 4
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File .\start-browser.ps1 -Silent 2>&1 | Out-Null
Start-Sleep -Seconds 12
& $py ele_query.py --date 2026-11-09 2>&1 | Select-Object -Last 3", "description": "Switch silent mode to offscreen window and test query", "timeoutMs": 400000}

