'''      <p>只读数据库 · 写操作不会发生</p>
      <div class="qrbox">
        <img id="qrImg" src="/api/qr" alt="扫码打开" />
        <div class="qrtext">
          <div class="qrtitle">手机扫码打开</div>
          <div class="qrurl" id="qrUrl">加载中…</div>
        </div>
      </div>''')

s = s.replace('''  .qrbox {''', '''  .qrbox {''')  # no-op guard
s = s.replace('''  .cov { font-size:11px;''',
'''  .qrbox { display:flex; align-items:center; gap:12px; justify-content:center;
           margin:18px auto 6px; padding:12px; max-width:360px;
           background:#fff; border-radius:12px; }
  .qrbox img { width:96px; height:96px; display:block; }
  .qrtext { text-align:left; }
  .qrtitle { font-size:12px; color:#6b7178; font-weight:600; }
  .qrurl { font-size:13px; color:#ff6a00; font-weight:700; margin-top:4px; word-break:break-all; }
  .cov { font-size:11px;''')

# 取地址填到文字里
js = '''
async function loadWhere() {
  try {
    const r = await fetch('/api/where');
    const j = await r.json();
    const el = document.getElementById('qrUrl');
    if (el && j.url) el.textContent = j.url;
    const img = document.getElementById('qrImg');
    if (img) img.src = '/api/qr?t=' + Date.now();
  } catch (e) {}
}
'''
s = s.replace("async function loadDash() {", js + "\nasync function loadDash() {", 1)
s = s.replace("loadDash();", "loadDash();\nloadWhere();", 1)
io.open(p, "w", encoding="utf-8").write(s)
print("前端二维码已加")
