async function ask(text) {
  if (!text.trim()) return;
  add('q', esc(text), '我');
  const box = add('', '查询中…', '助手');
  $('#go').disabled = true;
  try {
    const r = await fetch('/api/ask?q=' + encodeURIComponent(text));
    const j = await r.json();
    box.innerHTML = '<span class="tag">助手</span>' + fmt(j.answer || '没查到');
  } catch (e) {
    box.innerHTML = '<span class="tag">助手</span>请求失败：' + esc(e);
  } finally {
    $('#go').disabled = false;
    $('#q').value = '';
  }
}

$('#go').onclick = () => ask($('#q').value);
$('#q').addEventListener('keydown', e => { if (e.key === 'Enter') ask($('#q').value); });
document.querySelectorAll('.chip').forEach(c => c.onclick = () => ask(c.textC

