@'
import io
p = "web_app.py"
s = io.open(p, encoding="utf-8").read()

# 刷新按钮（放在 近30日 后面）
s = s.replace('''      <div class="range" data-k="30d">近30日</div>''',
'''      <div class="range" data-k="30d">近30日</div>
      <div class="range refresh" id="btnRefresh">↻ 刷新</div>''')

s = s.replace('''  .date-range { position:relative; cursor:pointer; }''',
'''  .refresh { background:#fff1e6; color:#e85d04; font-weight:700; }
  .refresh.busy { opacity:.6; }
  .date-range { position:relative; cursor:pointer; }''')

# 点击逻辑
js = '''
const btnRefresh = document.getElementById('btnRefresh');
if (btnRefresh) {
  btnRefresh.onclick = async () => {
    if (btnRefresh.classList.contains('busy')) return;
    btnRefresh.classList.add('busy');
    const old = btnRefresh.textContent;
    btnRefresh.textContent = '采集中…';
    try {
      const r = await fetch('/api/refresh', {cache: 'no-store'});
      const j = await r.json();
      if (j.running) { btnRefresh.textContent = '已在采集'; }
    } catch (e) {}

    const started = Date.now();
    const timer = setInterval(async () => {
      try {
        const s = await (await fetch('/api/refresh/status', {cache: 'no-store'})).json();
        if (!s.running) {
          clearInterval(timer);
          btnRefresh.classList.remove('busy');
          btnRefresh.textContent = s.ok ? '已更新' : '刷新失败';
          await loadDash();
          setTimeout(() => { btnRefresh.textContent = old; }, 2600);
        } else {
          const sec = Math.round((Date.now() - started) / 1000);
          btnRefresh.textContent = `采集中 ${sec}s`;
        }
      } catch (e) {}
    }, 2500);
  };
}
'''
s = s.replace("async function loadDash() {", js + "\nasync function loadDash() {", 1)
io.open(p, "w", encoding="utf-8").write(s)
print("前端刷新按钮已加")
