    b = p.chromium.connect_over_cdp("http://127.0.0.1:9222", timeout=60000)
    ctx = b.contexts[0]
    pg = ctx.new_page()
    pg.goto("https://melody.shop.ele.me/app/shop/546266599/#app.shop.dashboard", wait_until="domcontentloaded", timeout=45000)
    pg.wait_for_timeout(9000)
    out = pg.evaluate("""async () => {
        const body = {service:"OrderWebService", method:"queryAllOrders",
          params:{shopId:546266599, condition:{offset:0,limit:2,beginTime:"2026-11-13T00:00:00",endTime:"2026-11-13T23:59:59"}, allOrderQueryType:"FINISHED"},
          id:"p-"+Date.now(), metas:{appVersion:"1.0.0",appName:"melody",ksid:localStorage.getItem("ksid")||"",shopId:546266599}, ncp:"2.0.0"};
        const r = await fetch("https://app-api.shop.ele.me/fulfill/weborder/queryAllOrders/",
          {method:"POST",headers:{"content-type":"application/json"},credentials:"include",body:JSON.stringify(body)});
        const j = await r.json();
        const o = j.result.orders[0];
        const si = o.settlementInfo || {};
        const cp = si.customerPaidInfo || {};
        const ei = si.expectedIncomeInfo || {};
        const fees = (cp.feeGroup || []).flatMap(g => g.fees || []);
        return {
          cp_total: cp.total,
          cp_fees: fees.map(f => [f.name, f.price, f.priceSign]).slice(0, 6),
          ei_total: ei.total,
          ei_title: ei.title,
          ei_fees: (ei.feeGroup||[]).flatMap(g=>g.fees||[]).map(f => [f.name, f.price, f.priceSign]).slice(0, 8),
          orderTotalPrice: si.orderTotalPrice
        };
    }""")
    print(json.dumps(out, ensure_ascii=False, indent=1)[:1200])
    b.close()
