def _food_cost(c, start: str, end: str, platform: str,
               period_key: str = "yesterday") -> dict:
    """按菜单成本 × 销量算食材成本，返回 {cost, matched_qty, total_qty, unmatched}。"""
    menu = _menu_map(c)
    if not menu:
        return {"cost": None, "matched_qty": 0, "total_qty": 0, "unmatched": []}

    # 套餐子项的量是「串」，菜单成本是「份」，要先按倍数折回份数
    pairs = _pack_pairs()
    items: list[tuple[str, float]] = []

    def servings_per_unit(name: str, from_combo: bool) -> float:
        return _servings_per_unit(name)

    def add(name: str, q: float, from_combo: bool) -> None:
        n = servings_per_unit(name, from_combo)
        items.append((name, q / n if n > 1 else q))

    if platform == "meituan":
        try:
            for r in c.execute(
                """SELECT sku_name, SUM(qty) q FROM order_items
                   WHERE is_combo_parent = 0 AND parent_name IS NULL
                     AND order_no IN (SELECT order_no FROM orders
                                      WHERE date(created_at) BETWEEN ? AND ?
                                        AND status NOT LIKE '%取消%')
                   GROUP BY sku_name""",
                (start, end),
            ):
                add(r["sku_name"], r["q"] or 0, False)
            for r in c.execute(
                """SELECT sku_name, SUM(qty) q FROM order_items
                   WHERE is_combo_parent = 0 AND parent_name IS NOT NULL
                     AND order_no IN (SELECT order_no FROM orders
                                      WHERE date(created_at) BETWEEN ? AND ?
                                        AND status NOT LIKE '%取消%')
                   GROUP BY sku_name""",
                (start, end),
            ):
                add(r["sku_name"], r["q"] or 0, True)
        except Exception:  # noqa: BLE001
            pass
    else:
        portions_mode = False
        try:
            has_items = c.execute(
                """SELECT COUNT(*) FROM ele_order_items WHERE date BETWEEN ? AND ?""",
                (start, end),
            ).fetchone()[0] or 0
        except Exception:  # noqa: BLE001
            has_items = 0
        if has_items:
            portions_mode = True
            for r in c.execute(
                """SELECT item_name, is_combo, SUM(qty) q FROM ele_order_items
                   WHERE date BETWEEN ? AND ? GROUP BY item_name, is_combo""",
                (start, end),
            ):
                q = r["q"] or 0
                if r["is_combo"]:
                    # 套餐内：单位是「份」，直接按份计成本
                    items.append((r["item_name"], q))
                else:
