{"command": "cd "C:\Users\24380\Documents\deepseek-harness\default-workspace\meituan-agent"
$py = "C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe"
$env:PYTHONIOENCODING = "utf-8"
@'
import sys, sqlite3
from pathlib import Path
sys.path.insert(0, ".")
import dashboard as d

c = sqlite3.connect("data/shop.db"); c.row_factory = sqlite3.Row
menu = d._menu_map(c)

def explain(name):
    """返回 (成本分, 匹配到的菜单项, 是否精确)"""
    n = d._norm_name(name)
    if not n:
        return (None, "", False)
    if n in menu:
        return (menu[n], n, True)
    best, best_score, best_key = None, 0.0, ""
    for k, v in menu.items():
        if not k:
            continue
        if n in k or k in n:
            score = min(len(n), len(k)) / max(len(n), len(k))
            if score > best_score:
                best, best_score, best_key = v, score, k
    if best is not None and best_score >= 0.5:
        return (best, best_key, False)
    for k, v in menu.items():
        common = len(set(n) & set(k))
        if common >= 3:
            score = common / max(len(set(n)), len(set(k)))
            if score > best_score and score >= 0.75:
                best, best_score, best_key = v, score, k
    return (best, best_key, False)

rows = {}
for r in c.execute("""SELECT sku_name AS name, SUM(qty) q FROM order_items
                      WHERE order_no IN (SELECT order_no FROM orders
                        WHERE date(created_at) >= date('now','localtime','-30 day'))
                      GROUP BY sku_name"""):
    rows.setdefault(r["name"], [0, 0])
    rows[r["name"]][0] += r["q"] or 0
    rows[r["name"]][1] = 1

for r in c.execute("""SELECT item_name AS name, SUM(qty) q FROM ele_order_items
                      WHERE date >= date('now','localtime','-30 day')
                      GROUP BY item_name"""):
    rows.setdefault(r["name"], [0, 0])
    rows[r["name"]][0] += r["q"] or 0
    rows[r["name"]][1] = 2

NOTE = ("微辣","中辣","特辣","不辣","葱花","芝麻","纯碳烤","不要","默认","更多","进店爽吃","收藏","开业特惠","0元")

out = []
for name, (qty, src) in sorted(rows.items(), key=lambda kv: -kv[1][0]):
    if not name or qty <= 0:
        continue
    cost, key, exact = explain(name)
    if any(k in name for k in NOTE):
        kind = "备注/赠品"
    elif cost is None:
        kind = "未匹配"
    elif exact:
        kind = "精确"
    else:
        kind = "模糊匹配"
    out.append((name, qty, cost, key, kind))

lines = ["# 菜品成本核对（近30天）", "",
         "| 菜品 | 销量 | 成本/份 | 匹配到 | 状态 |", "|---|---|---|---|---|"]
for name, qty, cost, key, kind in out:
    cs = f"¥{cost/100:.2f}" if cost is not None else "—"
    lines.append(f"| {name} | {qty:.0f} | {cs} | {key or '—'} | {kind} |")
Path("data/cost_review.md").write_text("\n".join(lines), encoding="utf-8")

print("=== 可能误匹配（模糊）===")
n = 0
for name, qty, cost, key, kind in out:
    if kind == "模糊匹配":
        print(f"  {name}  (销量{qty:.0f})  →  {key} ¥{(cost or 0)/100:.2f}")
        n += 1
print(f"  共 {n} 个")
print("\n=== 未匹配 ===")
n2 = 0
for name, qty, cost, key, kind in out:
    if kind == "未匹配":
        print(f"  {name}  (销量{qty:.0f})")
        n2 += 1
print(f"  共 {n2} 个")
print(f"\n总菜品 {len(out)} 个，明细已写入 data/cost_review.md")
'@ | Set-Content scripts/audit_costs.py -Encoding utf8
& $py scripts\audit_costs.py 2>&1 | Select-Object -Last 45", "description": "Audit cost matching for all sold dishes", "timeoutMs": 180000}

