    const items = (o.items || []).map(it =>
      `<div class="it"><span>${esc(it.name)} ×${it.qty}${it.portions && Math.abs(it.portions - it.qty) > 0.01 ? '（' + it.portions.toFixed(1) + '份）' : ''}</span>
       <span>¥${(it.cost/100).toFixed(2)}</span></div>`).join('');
    return `<div class="ord" data-i="${i}">
      <div class="hd">
        <div>
          <div class="no">${pn} · ${esc(o.time)} · 单号 ${esc(String(o.no).slice(-6))}</div>
          <div class="sum">
            <div class="cell">顾客实付<b>¥${(o.paid/100).toFixed(2)}</b></div>
            <div class="cell">预计收入<b>¥${(o.income/100).toFixed(2)}</b></div>
            <div class="cell">食材成本<b>¥${(o.cost/100).toFixed(2)}</b></div>
