            const j = JSON.parse(t);
            const list = (j.data && (j.data.list || j.data.orderList)) || [];
            if (!list.length) return {status: r.status, keys: Object.keys(j), head: t.slice(0, 200)};
            const o = list[0];
            return {status: r.status, keys: Object.keys(o), sample: Object.fromEntries(Object.entries(o).filter(([k,v]) => typeof v !== "object").slice(0, 25))};
        } catch (e) { return {err: String(e), head: t.slice(0, 200)}; }
    }""")
    print(json.dumps(out, ensure_ascii=False)[:1200])
    b.close()
