def parse_order(raw: dict) -> dict:
    common = _json_field(raw.get("commonInfo"))
    info = _json_field(raw.get("orderInfo"))
    unified = info.get("unifiedOrderInfo", {}) or {}
    basic = unified.get("basicVo", {}) or {}
    charge = (info.get("chargeInfo", {}) or {}).get("fixedSettlementInfo", {}) or {}
    food = info.get("foodInfo", {}) or {}

    items = []
    for cart in food.get("cartDetailVos", []) or []:
        for detail in cart.get("details", []) or []:
            name = detail.get("foodName") or detail.get("name") or ""
            if not name:
                continue
            qty = detail.get("count") or detail.get("quantity") or 1
            price = detail.get("foodPrice") or detail.get("originFoodPrice") or 0
            subs = detail.get("subDetails") or []
