def _servings_per_unit(name: str) -> float:
    """每份多少串。优先级：倍数表 → 含「串」默认 10 → 其它按 1（个/份）。"""
    nm = name or ""
    mult, _key = _pack_mult(nm, _pack_pairs())
    if mult > 1:
        return mult
    if "串" in nm:
        return 10.0
    return 1.0

