 table{{width:100%;border-collapse:collapse;font-size:12.5px}}
 th,td{{padding:6px 4px;border-bottom:1px solid #f1f2f4;text-align:left;white-space:nowrap}}
 th{{color:#8a9099;font-weight:600;font-size:11.5px}}
 td.r,th.r{{text-align:right}} td.c,th.c{{text-align:center}}
 .tagx{{font-size:11px;padding:1px 6px;border-radius:8px;background:#eef1f4;color:#5a6169}}
 .tagx.精确{{background:#e6f7ee;color:#0a9e57}}
 .tagx.模糊{{background:#fff4e6;color:#d97706}}
 input{{width:100%;padding:9px 11px;border:1px solid #e3e5e8;border-radius:10px;font-size:14px;box-sizing:border-box;margin-bottom:8px}}
 a.back{{font-size:13px;color:#ff6a00;text-decoration:none}}
</style></head><body><div class="wrap">
