@'
import urllib.request, json
from datetime import date, timedelta

def num(v):
    try: return float(str(v).replace("¥","").replace(",","").replace("−","-"))
    except Exception: return 0.0

print("=== 近30日 汇总 ===")
d = json.load(urllib.request.urlopen("http://127.0.0.1:8000/api/dashboard?range=30d&platform=all"))
print("区间:", d["range"]["start"], "至", d["range"]["end"])
p = {m["label"]: m["value"] for m in [t for t in d["tabs"] if t["key"]=="profit"][0]["metrics"]}
for k in ("预计收入","食材成本","推广成本","刷单成本","毛利","固定成本","净利润"):
    if k in p: print(f"  {k}: {p[k]}")

print("\n=== 分平台（近30日）===")
for plat in ("meituan","eleme"):
    dd = json.load(urllib.request.urlopen(f"http://127.0.0.1:8000/api/dashboard?range=30d&platform={plat}"))
    pp = {m["label"]: (m["value"], m["delta"]["text"]) for m in [t for t in dd["tabs"] if t["key"]=="profit"][0]["metrics"]}
    print(f"{plat}:")
    for k in ("预计收入","食材成本","推广成本","刷单成本","毛利"):
        print(f"   {k}: {pp.get(k)}")

print("\n=== 逐日（近30日，按净利排序）===")
rows = []
start = date.fromisoformat(d["range"]["start"])
end = date.fromisoformat(d["range"]["end"])
day = start
while day <= end:
    ds = day.isoformat()
    try:
        dd = json.load(urllib.request.urlopen(f"http://127.0.0.1:8000/api/dashboard?range=date:{ds}&platform=all"))
        pp = {m["label"]: m["value"] for m in [t for t in dd["tabs"] if t["key"]=="profit"][0]["metrics"]}
        rev = num(pp.get("预计收入")); food = num(pp.get("食材成本")); net = num(pp.get("净利润"))
        gross = num(pp.get("毛利"))
        rows.append((ds, rev, food, net, gross))
    except Exception as e:
        pass
    day += timedelta(days=1)

rows.sort(key=lambda r: -r[3])
print(f"{'日期':<10}{'收入':>9}{'食材':>9}{'毛利率':>7}{'净利':>9}")
for ds, rev, food, net, gross in rows[:5]:
    print(f"{ds[5:]:<10}{rev:>9,.0f}{food:>9,.0f}{(gross/rev*100 if rev else 0):>6.1f}%{net:>9,.0f}")
print("   ...")
for ds, rev, food, net, gross in rows[-5:]:
    print(f"{ds[5:]:<10}{rev:>9,.0f}{food:>9,.0f}{(gross/rev*100 if rev else 0):>6.1f}%{net:>9,.0f}")

loss = [r for r in rows if r[3] < 0]
print(f"\n有数据 {len(rows)} 天，其中亏损 {len(loss)} 天，占比 {len(loss)/len(rows)*100:.0f}%")
print("平均日收入: ¥{:,.0f}".format(sum(r[1] for r in rows)/len(rows)))
print("平均日净利: ¥{:,.0f}".format(sum(r[3] for r in rows)/len(rows)))
'@ | Set-Content scripts/report_30d.py -Encoding utf8
& $py scripts\report_30d.py", "description": "Recompute last 30 days totals and daily stats", "timeoutMs": 400000}

