{"command": "cd "C:\Users\24380\Documents\deepseek-harness\default-workspace\meituan-agent"
$enc = New-Object System.Text.UTF8Encoding($true)
$content = @'
param(
    [int]$Port = 8000,
    [switch]$Open
)

# 启动「兵哥烧烤 · 数据助手」网页服务（后台无窗口运行）
$ErrorActionPreference = "Continue"
$here = $PSScriptRoot
$pydir = "C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python"
$py = Join-Path $pydir "python.exe"
$pyw = Join-Path $pydir "pythonw.exe"
if (-not (Test-Path $pyw)) { $pyw = $py }

# 已经在跑就直接退出，避免重复启动
$listening = Get-NetTCPConnection -LocalPort $Port -State Listen -ErrorAction SilentlyContinue
if ($listening) {
    if ($Open) { Start-Process "http://127.0.0.1:$Port" }
    exit 0
}

# 防火墙（需要管理员，失败不影响运行）
$rule = Get-NetFirewallRule -DisplayName "BBQ Data Assistant $Port" -ErrorAction SilentlyContinue
if (-not $rule) {
    try {
        New-NetFirewallRule -DisplayName "BBQ Data Assistant $Port" -Direction Inbound `
            -Protocol TCP -LocalPort $Port -Action Allow -Profile Private,Domain -ErrorAction Stop | Out-Null
    } catch {}
}

$ip = (Get-NetIPAddress -AddressFamily IPv4 |
    Where-Object { $_.IPAddress -notlike "127.*" -and $_.IPAddress -notlike "169.254.*" } |
    Select-Object -First 1).IPAddress
if (-not $ip) { $ip = "127.0.0.1" }

$logDir = Join-Path $here "logs"
if (-not (Test-Path $logDir)) { New-Item -ItemType Directory -Path $logDir | Out-Null }

# 后台启动，不弹任何窗口
Start-Process -FilePath $pyw -ArgumentList "web_app.py", "--port", "$Port" `
    -WorkingDirectory $here -WindowStyle Hidden `
    -RedirectStandardOutput (Join-Path $logDir "web_out.log") `
    -RedirectStandardError (Join-Path $logDir "web_err.log")

Start-Sleep -Seconds 3
$ok = Get-NetTCPConnection -LocalPort $Port -State Listen -ErrorAction SilentlyContinue
if ($ok) { Write-Host "服务已启动： http://${ip}:$Port" -ForegroundColor Green }
else { Write-Host "启动失败，详见 logs\web_err.log" -ForegroundColor Red }

if ($Open) { Start-Process "http://127.0.0.1:$Port" }
'@
[System.IO.File]::WriteAllText((Join-Path (Get-Location) "start_web.ps1"), $content, $enc)
"start_web.ps1 已改为后台无窗口启动"
Write-Output "=== 重启服务验证 ==="
Get-NetTCPConnection -LocalPort 8000 -State Listen -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id $_.OwningProcess -Force -ErrorAction SilentlyContinue }
Start-Sleep -Seconds 3
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File .\start_web.ps1
Start-Sleep -Seconds 2
try { "健康: " + (Invoke-RestMethod "http://127.0.0.1:8000/api/health" -TimeoutSec 5).ok } catch { "无响应" }
Get-CimInstance Win32_Process -Filter "Name='pythonw.exe'" | Select-Object ProcessId, @{n='Cmd';e={$_.CommandLine.Substring(0,[Math]::Min(70,$_.CommandLine.Length))}} | Format-Table -AutoSize", "description": "Rewrite web launcher to run windowless and test", "timeoutMs": 240000}

