@'
from playwright.sync_api import sync_playwright
import sys, json
sys.stdout.reconfigure(encoding="utf-8", errors="replace")
with sync_playwright() as p:
    b = p.chromium.connect_over_cdp("http://127.0.0.1:9222", timeout=60000)
    ctx = b.contexts[0]
    # 用已存在的 melody 标签页，而不是新开
    pages = [x for x in ctx.pages if "melody.shop.ele.me" in x.url]
    pg = pages[-1] if pages else ctx.new_page()
    if "melody.shop.ele.me" not in pg.url:
        pg.goto("https://melody.shop.ele.me/app/shop/546266599/#app.shop.dashboard", wait_until="domcontentloaded", timeout=60000)
        pg.wait_for_timeout(10000)
    pg.wait_for_timeout(5000)
    out = pg.evaluate("""async () => {
        const body = {service:"OrderWebService", method:"queryAllOrders",
          params:{shopId:546266599, condition:{offset:0,limit:2,beginTime:"2026-11-15T00:00:00",endTime:"2026-11-15T23:59:59"}, allOrderQueryType:"FINISHED"},
          id:"probe-"+Date.now(), metas:{appVersion:"1.0.0",appName:"melody",ksid:localStorage.getItem("ksid")||"",shopId:546266599}, ncp:"2.0.0"};
        try {
            const r = await fetch("https://app-api.shop.ele.me/fulfill/weborder/queryAllOrders/",
              {method:"POST",headers:{"content-type":"application/json"},credentials:"include",body:JSON.stringify(body)});
            const t = await r.text();
            return {status: r.status, len: t.length, head: t.slice(0, 120)};
        } catch (e) { return {error: String(e)}; }
    }""")
    print(json.dumps(out, ensure_ascii=False)[:300])
    b.close()
'@ | Set-Content scripts/probe_retry_query.py -Encoding utf8
& $py scripts\probe_retry_query.py", "description": "Retry order query after waiting", "timeoutMs": 300000}

