{"content": "# 首次配置：把店铺信息写进程序
# 用法：powershell -ExecutionPolicy Bypass -File .\setup_shop.ps1

$ErrorActionPreference = "Stop"
$root = $PSScriptRoot
Write-Host ""
Write-Host "=== 烧烤店经营看板 · 首次配置 ===" -ForegroundColor Cyan
Write-Host ""

$shopName = Read-Host "店铺名称（如：老王烧烤（XX店））"
if (-not $shopName) { $shopName = "我的烧烤店" }

$eleShopId = Read-Host "闪购店铺 ID（登录 melody.shop.ele.me 后地址栏 /app/shop/ 后面那串数字，直接回车跳过）"
$regionId = Read-Host "美团城市 region_id（直接回车用默认 1000350300）"
if (-not $regionId) { $regionId = "1000350300" }
$regionVer = "1792542949"

$oldEle = "546266599"
$changed = 0

if ($eleShopId -and $eleShopId -match '^\d+$') {
    Get-ChildItem -Path $root -Filter *.py | ForEach-Object {
        $text = Get-Content $_.FullName -Raw -Encoding UTF8
        if ($text -like "*$oldEle*") {
            $text = $text.Replace($oldEle, $eleShopId)
            [System.IO.File]::WriteAllText($_.FullName, $text, (New-Object System.Text.UTF8Encoding($false)))
            $changed++
        }
    }
    Write-Host "已把闪购店铺 ID 替换为 $eleShopId（改动 $changed 个文件）" -ForegroundColor Green
} else {
    Write-Host "跳过闪购 ID 替换（之后可手动改）" -ForegroundColor Yellow
}

if ($regionId -ne "1000350300") {
    Get-ChildItem -Path $root -Filter *.py | ForEach-Object {
        $text = Get-Content $_.FullName -Raw -Encoding UTF8
        if ($text -like "*1000350300*") {
            $text = $text.Replace("1000350300", $regionId)
            [System.IO.File]::WriteAllText($_.FullName, $text, (New-Object System.Text.UTF8Encoding($false)))
        }
    }
    Write-Host "已把美团 region_id 替换为 $regionId" -ForegroundColor Green
}

# 写入店铺配置
$cfg = [ordered]@{
    shop_name     = $shopName
    ele_shop_id   = $eleShopId
    region_id     = $regionId
    region_version= $regionVer
    created_at    = (Get-Date -Format "yyyy-MM-dd HH:mm:ss")
}
$cfgJson = $cfg | ConvertTo-Json -Depth 5
[System.IO.File]::WriteAllText((Join-Path $root "shop.json"), $cfgJson, (New-Object System.Text.UTF8Encoding($false)))
Write-Host "已生成 shop.json" -ForegroundColor Green

# 建库（表结构自动创建）
$dataDir = Join-Path $root "data"
if (-not (Test-Path $dataDir)) { New-Item -ItemType Directory -Path $dataDir | Out-Null }
$py = (Get-Command python -ErrorAction SilentlyContinue).Source
if ($py) {
    & $py -c "import sys; sys.path.insert(0, r'$root'); import db; conn = db.connect() if hasattr(db,'connect') else None; print('数据库已就绪')" 2>$null
    if (-not $?) { Write-Host "数据库将在首次采集时自动创建" -ForegroundColor Yellow }
} else {
    Write-Host "未检测到 python，请先安装 Python 并加入 PATH" -ForegroundColor Yellow
}

Write-Host ""
Write-Host "=== 配置完成 ===" -ForegroundColor Green
Write-Host "下一步：" -ForegroundColor Cyan
Write-Host "  1) powershell -ExecutionPolicy Bypass -File .\start-browser.ps1   ← 登录两个平台"
Write-Host "  2) powershell -ExecutionPolicy Bypass -File .\start_web.ps1        ← 启动看板"
Write-Host ""
", "file_path": "C:\Users\24380\Documents\deepseek-harness\default-workspace\meituan-agent\setup_shop.ps1"}

