content.arguments:
{"command": "cd "C:\Users\24380\Documents\deepseek-harness\default-workspace\meituan-agent"
$py = "C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe"
$env:PYTHONIOENCODING="utf-8"
@'
from playwright.sync_api import sync_playwright
import sys, re
sys.stdout.reconfigure(encoding="utf-8", errors="replace")
with sync_playwright() as p:
    b = p.chromium.connect_over_cdp("http://127.0.0.1:9222", timeout=60000)
    page = [x for x in b.contexts[0].pages if "e.waimai.meituan.com" in x.url][-1]
    page.wait_for_timeout(1500)
    pos = page.evaluate("""() => {
        const els = Array.from(document.querySelectorAll('*')).filter(e => e.children.length===0 && (e.textContent||'').trim()==='对账首页');
        if (!els.length) return null;
        const r = els[0].getBoundingClientRect();
        return {x: r.x + r.width/2, y: r.y + r.height/2, w: r.width, h: r.height, vis: r.width>0};
    }""")
    print("对账首页位置:", pos)
    if pos and pos.get("vis"):
        page.mouse.move(pos["x"]-2, pos["y"]); page.wait_for_timeout(300)
        page.mouse.click(pos["x"], pos["y"])
        print("坐标点击 ok")
    page.wait_for_timeout(15000)
    print("url:", page.url[:120])
    for i, f in enumerate(page.frames):
        try: t = f.inner_text("body")
        except Exception: continue
        if len(t) > 60 and ("账单" in t or "结算" in t or "对账" in t):
            print(f"[{i}] {f.url[:90]} len={len(t)}")
            print("   ", re.sub(r"\s+", " | ", t)[:600])
    b.close()
'@ | Set-Content scripts/click_reconcile2.py -Encoding utf8
& $py scripts\click_reconcile2.py 2>&1 | Select-Object -Last 14", "description": "Coordinate click on reconciliation page", "timeoutMs": 300000}

