from playwright.sync_api import sync_playwright
import sys, json
sys.stdout.reconfigure(encoding="utf-8", errors="replace")
with sync_playwright() as p:
    b = p.chromium.connect_over_cdp("http://127.0.0.1:9222", timeout=60000)
    ctx = b.contexts[0]
    pg = [x for x in ctx.pages if "melody.shop.ele.me" in x.url]
    page = pg[-1] if pg else ctx.new_page()
    page.wait_for_timeout(6000)
    out = page.evaluate("""async () => {
        const body = {service:"OrderWebService", method:"queryAllOrders",
          params:{shopId:546266599, condition:{offset:0,limit:20,beginTime:"2026-11-19T00:00:00",endTime:"2026-11-19T23:59:59"}, allOrderQueryType:"FINISHED"},
          id:"p-"+Date.now(), metas:{appVersion:"1.0.0",appName:"melody",ksid:localStorage.getItem("ksid")||"",shopId:546266599}, ncp:"2.0.0"};
        const r = await fetch("https://app-api.shop.ele.me/fulfill/weborder/queryAllOrders/",
          {method:"POST",headers:{"content-type":"application/json"},credentials:"include",body:JSON.stringify(body)});
        const j = await r.json();
        const o = (j.result.orders||[]).find(x => String(x.id).endsWith("138415"));
        if (!o) return {notfound:true};
        const items = [];
        for (const g of (o.foodInfo && o.foodInfo.groups) || []) {
            for (const it of g.items || []) {
                items.push({name: it.name, qty: it.quantity, isCombo: it.isCombo,
                            combo: (it.comboItems||[]).map(c => ({name: c.name, qty: c.quantity}))});
            }
        }
        return {order: String(o.id).slice(-6), items};
    }""")
    print(json.dumps(out, ensure_ascii=False, indent=1)[:1500])
    b.close()
