def _merge_metrics(a: list[dict], b: list[dict],
                   pairs: dict[str, tuple[str, str]], unit: str) -> list[dict]:
    """按「美团标签 -> (闪购标签, 输出标签)」把两边相加。"""
    amap = {m["label"]: m for m in a}
    bmap = {m["label"]: m for m in b}
    out: list[dict] = []
    for mt_label, spec in pairs.items():
        if len(spec) == 3:
            ele_label, out_label, unit_one = spec
        else:
            ele_label, out_label = spec
            unit_one = unit
        ma, mb = amap.get(mt_label), bmap.get(ele_label)
        if not ma and not mb:
            continue
        va = _num(ma["value"]) if ma else None
        vb = _num(mb["value"]) if mb else None
        if va is None and vb is None:
            continue
        cur = (va or 0) + (vb or 0)
        pa = _num(ma["delta"].get("prev")) if ma and ma.get("delta") else None
        pb = _num(mb["delta"].get("prev")) if mb and mb.get("delta") else None
        only = ""
        if ma and not mb and vb is None and ele_label:
            only = "" if ele_label else ""
        prev = None
        if pa is not None and pb is not None:
            prev = pa + pb
        elif pa is not None:
            prev = pa
        elif pb is not None:
            prev = pb

        if _is_pct(ma["value"]) if ma else False:
            value = f"{cur:.2f}%"
            money = False
        elif unit_one == "money":
            value = _yuan(int(round(cur * 100)))
            money = True
        else:
            value = f"{cur:,.0f}"
            money = False

        delta = {"text": "", "dir": "flat", "prev": ""}
        if prev is None:
            delta["text"] = "无对比数据"
        elif prev:
            scale = 100 if money else 1
            delta = _delta(cur * scale, prev * scale, money=money)

        out.append({"label": out_label, "value": value, "delta": delta})
    return out


BIZ_PAIRS = {
    "订单收入": ("收入", "订单收入", "money"),
    "优惠前总额": ("营业额", "优惠前总额", "money"),
    "补贴及支出": ("支出", "补贴及支出", "money"),
    "有效订单": ("有效订单", "有效订单", "count"),
    "佣金": ("", "佣金（美团）", "money"),
    "配送服务费": ("", "配送服务费（美团）", "money"),
    "打包费": ("", "打包费（美团）", "money"),
}

TRAFFIC_PAIRS = {
    "曝光人数": ("曝光人数", "曝光人数"),
    "入店人数": ("进店人数", "进店人数"),
    "下单人数": ("下单人数", "下单人数"),
}

新增合并时段统计
def _all(mt: dict, ele: dict) -> dict:
    out = {
        "business": _merge_metrics(mt["business"], ele["business"], BIZ_PAIRS, "money"),
        "traffic": _merge_metrics(mt["traffic"], ele["traffic"], TRAFFIC_PAIRS, "count"),
        "promo": _merge_metrics(
            mt["promo"], ele["promo"],
            {"推广花费(今日)": ("推广消耗(今日)", "推广花费"),
             "推广曝光(今日)": ("曝光提升(今日)", "推广曝光"),
             "推广进店(今日)": ("进店提升(今日)", "推广进店")},
            "money",
        ),
        "marketing": _merge_metrics(mt["marketing"], ele["marketing"], {}, "money") or mt["marketing"],
        "goods": _merge_goods(mt["goods"], ele["goods"]),
        "timeline": mt.get("timeline"),
        "time": mt["time"] + (ele.get("time") or [])[:2],
        "fake": _fake_combined(mt, ele),
        "profit": _profit_combined(mt, ele),
        "top": mt.get("top"),
        "note": "美团 + 闪购 合计",
        "has_orders": True,
    }
    for m in out.get("profit", []):
        if (m.get("delta") or {}).get("text") == "无对比数据":
            m["delta"]["text"] = ""

    # 单均价：两种口径都给出，避免混淆
    def pick(metrics, label, field="value"):
        for m in metrics:
            if m["label"] == label:
                return

def _goods_rows(c, start: str, end: str, platform: str,
                period_key: str = "yesterday") -> list[dict]:
    """返回 [{name, plain(串), combo(份), amount}]。

    单点按「串」计；套餐按「份」计（套餐内 1 份 = 每份串数）。
    """
    rows: dict[str, dict] = {}

    def add(name: str, plain: float, combo: float, amount: float = 0.0) -> None:
        if not name or name.startswith("----"):
            return
        r = rows.setdefault(name, {"name": name, "plain": 0.0, "combo": 0.0, "amount": 0.0})
        r["plain"] += plain
        r["combo"] += combo
        r["amount"] += amount

    if platform == "meituan":
        for r in c.execute(
            """SELECT sku_name, parent_name, SUM(qty) q, SUM(amount_cents) a
               FROM order_items
               WHERE is_combo_parent = 0
                 AND order_no IN (SELECT order_no FROM orders
                                  WHERE date(created_at) BETWEEN ? AND ?
                                    AND status NOT LIKE '%取消%')
               GROUP BY sku_name, (parent_name IS NOT NULL)""",
            (start, end),
        ):
            served = _servings_per_unit(r["sku_name"]) or 1
            if r["parent_name"]:
                add(r["sku_name"], 0, (r["q"] or 0) / served, r["a"] or 0)
            else:
                add(r["sku_name"], r["q"] or 0, 0, r["a"] or 0)
    else:
        for r in c.execute(
            """SELECT item_name, SUM(qty) q, SUM(amount_cents) a FROM ele_goods
               WHERE period = ? GROUP BY item_name""", (period_key,)):
            nm = r["item_name"] or ""
            if "｜" in nm or "【" in nm or nm in ("招牌", "套餐", "商品"):
                continue
            add(nm, r["q"] or 0, 0, r["a"] or 0)
        for r in c.execute(
            """SELECT sub_name, SUM(raw_qty) rq FROM ele_combo_items
               WHERE date BETWEEN ? AND ? GROUP BY sub_name""",
            (start, end),
        ):
            add(r["sub_name"], 0, r["rq"] or 0)

    out = list(rows.values())
    for r in out:
        served = _servings_per_unit(r["name"]) or 1
        r["stick_eq"] = r["plain"] + r["combo"] * served
    out.sort(key=lambda r: -r["stick_eq"])
    return out

def _merge_goods(a: list[dict], b: list[dict]) -> list[dict]:
    """汇总：两边都已是「份」，按名称相加即可。"""
    rows: dict[str, dict] = {}
    for metrics in (a, b):
        for m in metrics:
            name = m["label"]
            r = rows.setdefault(name, {"name": name, "portions": 0.0, "amount": 0.0})
            r["portions"] += _num(m.get("value")) or 0
            txt = (m.get("delta") or {}).get("text") or ""
            if "套餐内" not in txt:
                r["amount"] += (_num(txt) or 0.0) * 100
    ranked = sorted(rows.values(), key=lambda r: -r["portions"])[:24]
    out = []
    for r in ranked:
        note = _yuan(int(r["amount"])) if r["amount"] else "套餐内"
        out.append({"label": r["name"][:12], "value": f"{r['portions']:,.1f} 份",
                    "delta": {"text": note, "dir": "flat"}})
    return out

