def parse_pending(text: str) -> dict[str, tuple[int, str]]:
    """未结算：返回 {账单日: (金额分, 预计入账日 YYYY-MM-DD)}。"""
    out: dict[str, tuple[int, str]] = {}
    for m in PENDING_RE.finditer(text):
        out[m.group(1)] = (
            int(round(float(m.group(2).replace(",", "")) * 100)),
            m.group(3),
        )
    return out


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--pages", type=int, default=1)

page = pages[-1] if pages else ctx.new_page()

page.goto(BILL_URL, wait_until="domcontentloaded", timeout=60000)

def find_frame():
    """找内容最长的 settleBill 内层 frame（外层 shell 只有菜单）。"""
    best = None
    for f in page.frames:
        if "settleBill" not in f.url or "waimaieapp.meituan.com" not in f.url:
            continue
        try:
            t = f.inner_text("body")
        except Exception:  # noqa: BLE001
            continue
        if best is None or len(t) > len(best[1]):
            best = (f, t)
    if best and len(best[1]) > 200:
        return best[0]
    return None

frame = None
for _ in range(10):
    page.wait_for_timeout(3000)
    frame = find_frame()
    if frame is not None:
        break

if frame is None:
