{"command": "$p = "D:\Work\兵哥烧烤\meituan-agent"
foreach ($f in @("hidden.vbs","run_daily.ps1","watch_web.ps1","start_web.ps1")) {
  $fp = Join-Path $p $f
  if (Test-Path $fp) { "$f OK" } else { "$f 缺失" }
}
Write-Output "=== 逐个改计划任务路径 ==="
$pairs = @(
  @{n="DSH-Shangpu-Daily";        tr="wscript.exe `"$p\hidden.vbs`" `"powershell.exe`" `"-NoProfile -ExecutionPolicy Bypass -File $p\run_daily.ps1`""},
  @{n="DSH-Shangpu-WebWatch";    tr="wscript.exe `"$p\hidden.vbs`" `"powershell.exe`" `"-NoProfile -ExecutionPolicy Bypass -File $p\watch_web.ps1`""},
  @{n="DSH-Shangpu-Refresh30";   tr="wscript.exe `"$p\hidden.vbs`" `"powershell.exe`" `"-NoProfile -ExecutionPolicy Bypass -Command & C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe $p\refresh.py *>> $p\logs\refresh.log`""},
  @{n="DSH-Shangpu-UnblockHourly"; tr="powershell.exe -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -Command `"Get-ChildItem -LiteralPath '$p','C:\Users\24380\Desktop' -Recurse -Include *.cmd,*.vbs,*.ps1,*.bat -ErrorAction SilentlyContinue | ForEach-Object { Unblock-File -LiteralPath `$_.FullName -ErrorAction SilentlyContinue }`""},
  @{n="DSH-Shangpu-Web";         tr="powershell.exe -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$p\start_web.ps1`""}
)
foreach ($x in $pairs) {
  $out = schtasks /Change /TN $x.n /TR $x.tr 2>&1
  "$($x.n): $out"
}", "description": "Repoint scheduled tasks to new project path", "timeoutMs": 180000}

