{"command": "$p = "D:\Work\兵哥烧烤\meituan-agent"
$vbs = "$p\hidden.vbs"
function Fix($name, $exe, $argstr) {
  try {
    $act = New-ScheduledTaskAction -Execute $exe -Argument $argstr
    Set-ScheduledTask -TaskName $name -Action $act -ErrorAction Stop | Out-Null
    "OK  $name"
  } catch { "FAIL $name : $($_.Exception.Message)" }
}
Fix "DSH-Shangpu-Daily"  "wscript.exe" "`"$vbs`" `"powershell.exe`" `"-NoProfile -ExecutionPolicy Bypass -File $p\run_daily.ps1`""
Fix "DSH-Shangpu-WebWatch" "wscript.exe" "`"$vbs`" `"powershell.exe`" `"-NoProfile -ExecutionPolicy Bypass -File $p\watch_web.ps1`""
Fix "DSH-Shangpu-Refresh30" "wscript.exe" "`"$vbs`" `"powershell.exe`" `"-NoProfile -ExecutionPolicy Bypass -Command & C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe $p\refresh.py >> $p\logs\refresh.log 2>&1`""
Fix "DSH-Shangpu-UnblockHourly" "powershell.exe" "-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -Command Get-ChildItem -LiteralPath '$p','C:\Users\24380\Desktop' -Recurse -Include *.cmd,*.vbs,*.ps1,*.bat -ErrorAction SilentlyContinue | ForEach-Object { Unblock-File -LiteralPath `$_.FullName -ErrorAction SilentlyContinue }"
Fix "DSH-Shangpu-Web" "powershell.exe" "-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$p\start_web.ps1`""
Write-Output "=== 改后确认 ==="
Get-ScheduledTask -TaskName "DSH-Shangpu-*" | ForEach-Object { "$($_.TaskName): " + (($_.Actions | ForEach-Object { "$($_.Execute) $($_.Arguments)" }) -join " | ") }", "description": "Fix task actions with Set-ScheduledTask", "timeoutMs": 180000}

