{"command": "$p = "D:\Work\兵哥烧烤\meituan-agent"
$py = "C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe"
$env:PYTHONIOENCODING="utf-8"
@'
import json, urllib.request
for plat in ("all","meituan","eleme"):
    u = f"http://127.0.0.1:8000/api/dashboard?range=date:2026-11-22&platform={plat}"
    d = json.load(urllib.request.urlopen(u, timeout=30))
    biz = next(t for t in d["tabs"] if t["key"]=="business")["metrics"]
    prof = next(t for t in d["tabs"] if t["key"]=="profit")["metrics"]
    print("==", plat, "==")
    for m in biz:
        if m["label"] in ("订单收入","有效订单","优惠前总额"):
            print("  ", m["label"], m["value"], (m.get("delta") or {}).get("text",""))
    for m in prof:
        if m["label"] in ("预计收入","到账总额","食材成本","推广成本","刷单成本","毛利","固定成本","净利润"):
            print("  ", m["label"], m["value"], "|", (m.get("delta") or {}).get("text",""))
'@ | Set-Content "$p\scripts\check_api_1122.py" -Encoding utf8
& $py "$p\scripts\check_api_1122.py"", "description": "Verify 11-22 numbers via dashboard API", "timeoutMs": 180000}

