$env:PYTHONIOENCODING="utf-8"
@'
import sqlite3
c = sqlite3.connect(r"D:\Work\兵哥烧烤\meituan-agent\data\shop.db")
for q, label in (
    ("select max(order_date) from orders", "orders 最新日期"),
    ("select max(order_date) from ele_orders", "ele_orders 最新日期"),
    ("select max(date) from ele_daily", "ele_daily 最新日期"),
    ("select max(date) from settle_daily", "settle_daily 最新日期"),
):
    try:
        print(label, "=", c.execute(q).fetchone()[0])
    except Exception as e:
        print(label, "err", e)
for d in ("2026-11-23", "2026-11-24"):
    try:
        a = c.execute("select count(*), coalesce(sum(pay_amount),0) from orders where order_date=?", (d,)).fetchone()
        print(d, "美团:", a)
    except Exception as e:
        print(d, "err", e)
c.close()
