{"command": "Write-Output "=== python 相关的入站允许规则 ==="
Get-NetFirewallRule -Direction Inbound -Enabled True -Action Allow -ErrorAction SilentlyContinue | ForEach-Object {
  $app = $_. | Out-Null
  $filter = $_ | Get-NetFirewallApplicationFilter -ErrorAction SilentlyContinue
  if ($filter -and $filter.Program -match "python") {
    [pscustomobject]@{ Name = $_.DisplayName; Profile = $_.Profile; Program = $filter.Program }
  }
} | Format-Table -AutoSize
Write-Output "=== Tailscale 后端状态 ==="
$ts = "C:\Program Files\Tailscale\tailscale.exe"
$o = (& $ts status --json 2>&1 | Out-String) | ConvertFrom-Json
