{"command": "Write-Output "=== python 相关的入站允许规则 ==="
$rules = Get-NetFirewallRule -Direction Inbound -Enabled True -Action Allow -ErrorAction SilentlyContinue
$hit = @()
foreach ($r in $rules) {
  $f = $r | Get-NetFirewallApplicationFilter -ErrorAction SilentlyContinue
  if ($f -and $f.Program -like "*python*") {
    $hit += [pscustomobject]@{ Name = $r.DisplayName; Profile = $r.Profile; Program = $f.Program }
  }
}
if ($hit.Count -eq 0) { "没有 python 的程序级规则" } else { $hit | Format-Table -AutoSize }
Write-Output "=== Tailscale 状态 ==="
$ts = "C:\Program Files\Tailscale\tailscale.exe"
$o = (& $ts status --json 2>&1 | Out-String) | ConvertFrom-Json
