srv.bind(("0.0.0.0", 8000))
'@ | Out-Null
# 用 PowerShell 侧监听日志：直接看 8000 的并发连接
$deadline = (Get-Date).AddSeconds(75)
$seen = @{}
"监听开始 $(Get-Date -Format 'HH:mm:ss')，等待手机连接..."
while ((Get-Date) -lt $deadline) {
  $conns = Get-NetTCPConnection -LocalPort 8000 -State Established -ErrorAction SilentlyContinue
  foreach ($c in $conns) {
    $key = "$($c.RemoteAddress):$($c.RemotePort)"
    if (-not $seen.ContainsKey($key)) {
      $seen[$key] = 1
      "连接来自 $key @ $(Get-Date -Format 'HH:mm:ss')"
    }
  }
  Start-Sleep -Milliseconds 700
}
"监听结束，共 $($seen.Count) 个不同源"", "description": "Watch port 8000 for incoming connections", "timeoutMs": 120000}

