{"command": "$ts = "C:\Program Files\Tailscale\tailscale.exe"
Write-Output "=== 设备状态 ==="
& $ts status 2>&1 | Select-Object -First 6
Write-Output "=== ping 手机 ==="
& $ts ping xiaomi-14 2>&1 | Select-Object -First 3
Write-Output "=== 监听 8000 外部连接（40 秒） ==="
$deadline = (Get-Date).AddSeconds(40)
$seen = @{}
while ((Get-Date) -lt $deadline) {
  Get-NetTCPConnection -LocalPort 8000 -State Established -ErrorAction SilentlyContinue |
    Where-Object { $_.RemoteAddress -notlike "127.*" } |
    ForEach-Object { $seen["$($_.RemoteAddress):$($_.RemotePort)"] = 1 }
  Start-Sleep -Milliseconds 600
}
if ($seen.Count -gt 0) { "有外部连接: " + ($seen.Keys -join ", ") } else { "40 秒内无外部连接（手机还没打开页面）" }", "description": "Check phone connection state and listen for traffic", "timeoutMs": 180000}

