      const snippet = i >= 0 ? body.slice(Math.max(0,i-40), i+20) : '(未找到)';
      // 找 textContent 含“出餐”的最小元素
      const cands = [];
      for (const el of document.querySelectorAll('*')) {
        const t = (el.textContent || '');
        if (t.includes('出餐完成')) {
          cands.push({tag: el.tagName, cls: String(el.className).slice(0,50), tl: t.length});
        }
      }
      cands.sort((a,b)=>a.tl-b.tl);
      return {snippet, codes: i>=0 ? [...body.slice(i-2, i+8)].map(c=>c.charCodeAt(0)) : [],
              smallest: cands.slice(0,5)};
    }""")
    print(json.dumps(r, ensure_ascii=False, indent=2))
    b.close()
