import re, sys
from playwright.sync_api import sync_playwright

SCAN_JS = """() => {
  const out = [];
  const cards = [];
  for (const el of document.querySelectorAll('*')) {
    const t = el.textContent || '';
    if (t.includes('参考出餐时长') && t.includes('出餐完成') && t.length < 3000) cards.push(el);
  }
  // 只保留最内层卡片
  const inner = cards.filter(el => !cards.some(o => o !== el && el.contains(o)));
  inner.forEach((card, i) => {
    const t = (card.textContent || '').replace(/\\s+/g, ' ');
    const mEl = t.match(/用时 ?(\\d{1,2}):(\\d{2})/);
    const mRef = t.match(/参考出餐时长 ?(?:(\\d+)分)?(\\d+)秒/);
    const mSn = t.match(/#(\\d+)/);
    if (!mEl || !mRef) return;
    const elapsed = parseInt(mEl[1]) * 60 + parseInt(mEl[2]);
    const ref = parseInt(mRef[1] || 0) * 60 + parseInt(mRef[2]);
    const btn = [...card.querySelectorAll('*')].find(e => (e.textContent || '').trim() === '出餐完成');
    if (btn) btn.setAttribute('data-meal-target', String(i));
    out.push({i: i, sn: mSn ? parseInt(mSn[1]) : null, elapsed: elapsed, ref: ref,
              remain: ref - elapsed, hasBtn: !!btn});
  });
  return out;
}"""

with sync_playwright() as p:
    b = p.chromium.connect_over_cdp("http://127.0.0.1:9222", timeout=60000)
    pg = [x for ctx in b.contexts for x in ctx.pages if "e.waimai.meituan.com" in x.url][0]
    f = None
    for fr in pg.frames:
        try:
            if "region_id" in fr.url and len(fr.inner_text("body")) > 1000:
                f = fr; break
        except Exception:
            pass
    rows = f.evaluate(SCAN_JS)
    print("待出餐订单:", len(rows))
    for r in rows:
        mm, ss = divmod(r["elapsed"], 60)
        print(f'  #{r["sn"]}  用时 {mm:02d}:{ss:02d}  参考 {r["ref"]}秒  剩余 {r["remain"]}秒  按钮 {r["hasBtn"]}')
    b.close()
