{"file_path": "E:\Work\兵哥烧烤\meituan-agent\auto_meal.py", "content": """"自动出餐上报 —— 用时快到「参考出餐时长」时自动点「出餐完成」。

逻辑：
  1. 连上已登录的美团后台（CDP 9222）。
  2. 找到「订单管理 → 全部订单」的内层 frame。
  3. 扫描所有处于「待出餐」的订单，读 `用时 mm:ss` 与 `参考出餐时长 X分Y秒`。
  4. 当 (参考 − 用时) <= 30 秒 时，点这张卡片的「出餐完成」，并处理可能出现的确认弹窗。
  5. 记录到 logs/auto_meal.log。

用法：
  python auto_meal.py --dry             # 只看不点
  python auto_meal.py                   # 扫一次，该点的点掉
  python auto_meal.py --watch           # 常驻，每 15 秒扫一次
  python auto_meal.py --watch --interval 20 --ahead 30
"""

from __future__ import annotations

import argparse
import datetime as dt
import sys
import time
from pathlib import Path

CDP_URL = "http://127.0.0.1:9222"
ROOT = Path(__file__).parent
LOG = ROOT / "logs" / "auto_meal.log"

SCAN_JS = """() => {
  const out = [];
  const btns = [...document.querySelectorAll('*')]
      .filter(el => (el.innerText || '').trim() === '出餐完成' && el.offsetParent !== null);
  const seen = new Set();
  btns.forEach((btn) => {
    let card = btn, d = 0;
    while (card && d < 14) {
      const it = card.innerText || '';
      if (it.includes('参考出餐时长') && it.includes('用时')) break;
      card = card.parentElement; d++;
    }
    if (!card || seen.has(card)) return;
