$env:PYTHONIOENCODING="utf-8"
@'
from playwright.sync_api import sync_playwright
import json
with sync_playwright() as p:
    b = p.chromium.connect_over_cdp("http://127.0.0.1:9222", timeout=60000)
    el = [pg for ctx in b.contexts for pg in ctx.pages if "ele.me" in pg.url][0]
    f = [fr for fr in el.frames if "napos-order-pc" in fr.url][0]
    t = f.inner_text("body")
    print("=== 页面文本（前 500）===")
    print(t[:500].replace("\n", " | "))
    info = f.evaluate("""() => {
      const out = [];
      for (const el of document.querySelectorAll('*')) {
        const t = (el.innerText || '').trim();
        if (t === '上报出餐' && el.offsetParent !== null) {
          let card = el, d = 0;
          while (card && d < 14) {
            const it = card.innerText || '';
            if (it.includes('出餐用时') && it.includes('建议')) break;
            card = card.parentElement; d++;
          }
          out.push({tag: el.tagName, cls: String(el.className).slice(0,50), depth: d,
                    card: card ? (card.innerText || '').replace(/\\s+/g,' ').slice(0,220) : null});
        }
      }
      return out;
    }""")
    print("\n=== 上报出餐 按钮 ===")
    print(json.dumps(info, ensure_ascii=False, indent=2)[:1500])
    b.close()
