from playwright.sync_api import sync_playwright
import json, time
CLICK = """() => {
  const cards = [...document.querySelectorAll('[class*="meal-complete-content_"]')];
  for (const card of cards) {
    const t = (card.innerText || '').replace(/\\s+/g, ' ');
    if (!t.includes('出餐用时') || t.includes('已出餐')) continue;
    const btn = [...card.querySelectorAll('button')].find(e => (e.innerText||'').trim() === '上报出餐');
    if (!btn) continue;
    ['mousedown','mouseup','click'].forEach(type => {
      btn.dispatchEvent(new MouseEvent(type, {bubbles: true, cancelable: true, view: window}));
    });
    return {clicked: true, text: t.slice(0, 60)};
  }
  return {clicked: false};
}"""
with sync_playwright() as p:
    b = p.chromium.connect_over_cdp("http://127.0.0.1:9222", timeout=60000)
    el = [pg for ctx in b.contexts for pg in ctx.pages if "ele.me" in pg.url][0]
    f = [fr for fr in el.frames if "napos-order-pc" in fr.url][0]
    r = f.evaluate(CLICK)
    print("点击结果:", json.dumps(r, ensure_ascii=False))
    time.sleep(2.5)
    # 看是否弹出确认框
    modal = f.evaluate("""() => {
      const out = [];
      document.querySelectorAll('.ant-modal, [class*="modal"]').forEach(m => {
        const t = (m.innerText || '').replace(/\\s+/g,' ');
        if (t && m.offsetParent !== null) out.push(t.slice(0, 120));
      });
      return out.slice(0, 3);
    }""")
    print("弹窗:", modal)
    after = f.evaluate("""() => {
      const cards = [...document.querySelectorAll('[class*="meal-complete-content_"]')];
      return cards.map(c => (c.innerText||'').replace(/\\s+/g,' ').slice(0, 70));
    }""")
    print("点击后卡片:")
    for a in after:
        print("   ", a)
    b.close()
