"""

from __future__ import annotations

import argparse
import datetime as dt
import sys
import time
from pathlib import Path

CDP_URL = "http://127.0.0.1:9222"
ROOT = Path(__file__).parent
LOG = ROOT / "logs" / "auto_meal.log"

# ---------------------------------------------------------------- 美团

MT_SCAN_JS = """() => {
  const out = [];
  const btns = [...document.querySelectorAll('*')]
      .filter(el => (el.innerText || '').trim() === '出餐完成' && el.offsetParent !== null);
  const seen = new Set();
  btns.forEach((btn) => {
    let card = btn, d = 0;
    while (card && d < 14) {
      const it = card.innerText || '';
      if (it.includes('参考出餐时长') && it.includes('用时')) break;
      card = card.parentElement; d++;
    }
    if (!card || seen.has(card)) return;
    seen.add(card);
    const it = (card.innerText || '').replace(/\\s+/g, ' ');
    let snText = it, up = card, ud = 0;
    while (!/#\\d+/.test(snText) && up && ud < 6) { up = up.parentElement; ud++; snText = up ? (up.innerText || '') : ''; }
    const el = it.match(/用时 ?(\\d{1,2}):(\\d{2})/);
    const rf = it.match(/参考出餐时长 ?(?:(\\d+)分)? ?(\\d+)秒/);
    if (!el || !rf) return;
    const elapsed = (+el[1]) * 60 + (+el[2]);
    const ref = (+(rf[1] || 0)) * 60 + (+rf[2]);
    btn.setAttribute('data-meal-target', '1');
    out.push({sn: (snText.match(/#(\\d+)/) || [null, null])[1], elapsed, ref, remain: ref - elapsed});
  });
  return out;
}"""

MT_CONFIRM_JS = """() => {
  const words = ['确认出餐', '确认', '确定', '提交'];
  for (const w of words) {
    const els = [...document.querySelectorAll('button, div, span, a')]
      .filter(el => (el.innerText || '').trim() === w && el.offsetParent !== null);
    if (els.length) { els[els.length - 1].setAttribute('data-meal-confirm', '1'); return w; }
  }
  return '';
}"""

# ---------------------------------------------------------------- 闪购

ELE_SCAN_JS = """() => {
  const out = [];
  const cards = [...document.querySelectorAll('[class*="meal-complete-content_"]')];
  cards.forEach((card) => {
    const t = (card.innerText || '').replace(/\\s+/g, ' ');
    if (!t.includes('出餐用时')) return;
    if (t.includes('已出餐')) return;                 // 已经报过了
    const btn = [...card.querySelectorAll('button')]
        .find(e => (e.innerText || '').trim() === '上报出餐');
    if (!btn) return;
    const mEl = t.match(/出餐用时 ?(?:(\\d+)分)? ?(\\d+)秒/);
    const mRf = t.match(/建议 ?(?:(\\d+)分)? ?(\\d+)秒内出餐/);
    if (!mEl || !mRf) return;
    const elapsed = (+(mEl[1] || 0)) * 60 + (+mEl[2]);
    const ref = (+(mRf[1] || 0)) * 60 + (+mRf[2]);
    let snText = t, up = card, ud = 0;
    while (!/#\\d+/.test(snText) && up && ud < 8) { up = up.parentElement; ud++; snText = up ? (up.innerText || '') : ''; }
    btn.setAttribute('data-meal-target', '1');
    out.push({sn: (snText.match(/#(\\d+)/) || [null, null])[1], elapsed, ref, remain: ref - elapsed});
  });
  return out;
}"""

ELE_CLICK_JS = """() => {
  const btn = document.querySelector('button[data-meal-target="1"]');
  if (!btn) return '找不到按钮';
  ['mousedown', 'mouseup', 'click'].forEach(type => {
    btn.dispatchEvent(new MouseEvent(type, {bubbles: true, cancelable: true, view: window}));
  });
  return '已点击';
}"""


def log(msg: str) -> None:
    line = f"[{dt.datetime.now():%Y-%m-%d %H:%M:%S}] {msg}"
    print(line, flush=True)
    LOG.parent.mkdir(parents=True, exist_ok=True)
    with LOG.open("a", encoding="utf-8") as fh:
        fh.write(line + "\n")


# ---------------------------------------------------------------- 美团实现


def mt_frame(page):
    for fr in page.frames:
        try:
            if "region_id" in fr.url and len(fr.inner_text("body")) > 1000:
                return fr
        except Exception:  # noqa: BLE001
            continue
    return None


def mt_ensure_order_page(page) -> bool:
    if mt_frame(page):
        return True
    try:
        shell = page.frames[0]
        shell.click("text=订单管理", timeout=8000)
        time.sleep(1.5)
        shell.click("text=全部订单", timeout=8000)
        time.sleep(3.0)
    except Exception as exc:  # noqa: BLE001
        log(f"美团打开订单页失败：{type(exc).__name__}: {exc}")
        return False
    return mt_frame(page) is not None


def mt_click(fr) -> str:
    btn = fr.query_selector('[data-meal-target="1"]')
    if not btn:
        return "找不到按钮"
    btn.click(timeout=8000)
    time.sleep(1.2)
    for _ in range(2):
        try:
            fr.evaluate(MT_CONFIRM_JS)
            c = fr.query_selector('[data-meal-confirm="1"]')
            if not c:
                break
            c.click(timeout=5000)
            time.sleep(1.2)
        except Exception:  # noqa: BLE001
            break
    try:
        if "已出餐" in fr.inner_text("body"):
            return "已点击（页面已显示已出餐）"
    except Exception:  # noqa: BLE001
        pass
    return "已点击"


# ---------------------------------------------------------------- 闪购实现


def ele_page(browser):
    return next((p for ctx in browser.contexts for p in ctx.pages if "ele.me" in p.url), None)


def ele_frame(page):
    for fr in page.frames:
        try:
            if "napos-order-pc" in fr.url and "出餐" in fr.inner_text("body"):
                return fr
        except Exception:  # noqa: BLE001
            continue
    return None


def ele_ensure_page(page) -> bool:
    if ele_frame(page):
        return True
    for fr in page.frames:
        try:
            if fr.query_selector("text=订单查询"):
                fr.click("text=订单查询", timeout=6000)
                time.sleep(3.0)
                break
        except Exception:  # noqa: BLE001
            continue
    return ele_frame(page) is not None


def ele_click(fr) -> str:
    r = fr.evaluate(ELE_CLICK_JS)
    if r == "找不到按钮":
        return r
    time.sleep(1.6)
    try:
        cards = fr.evaluate("""() => [...document.querySelectorAll('[class*="meal-complete-content_"]')]
            .map(c => (c.innerText || '').replace(/\\s+/g, ' '))""")
        if any("已出餐" in c for c in cards):
            return "已点击（页面已显示已出餐）"
    except Exception:  # noqa: BLE001
        pass
    return "已点击"


# ---------------------------------------------------------------- 主流程


_seen: dict[str, int] = {}


def handle_rows(rows, platform: str, ahead: int, dry: bool, clicker) -> int:
    acted = 0
    for r in rows:
        key = f"{platform}:{r.get('sn') or '?'}"
        sn = r.get("sn") or "?"
        el, ref, rem = r["elapsed"], r["ref"], r["remain"]
        label = "美团" if platform == "meituan" else "闪购"
        line = f"[{label}] #{sn} 用时{el // 60}分{el % 60:02d}秒 建议{ref // 60}分{ref % 60:02d}秒 剩余{rem}秒"
        if rem > ahead:
            if key not in _seen:
                _seen[key] = 1
                log(f"发现待出餐 {line} → 到点自动上报")
            elif rem // 60 != _seen[key]:
                _seen[key] = rem // 60
                log(f"{line} → 继续等待")
            continue
        if dry:
            log(f"[演练] {line} → 该点了（未执行）")
            continue
        result = clicker()
        log(f"{line} → {result}")
        _seen.pop(key, None)
        acted += 1
    return acted


def scan_mt(page, ahead: int, dry: bool) -> int:
    fr = mt_frame(page)
    if not fr:
        if not mt_ensure_order_page(page):
            return 0
        fr = mt_frame(page)
        if not fr:
            return 0
    try:
        rows = fr.evaluate(MT_SCAN_JS)
    except Exception as exc:  # noqa: BLE001
        log(f"美团扫描失败：{type(exc).__name__}: {exc}")
        return 0
    return handle_rows(rows, "meituan", ahead, dry, lambda: mt_click(fr))


def scan_ele(page, ahead: int, dry: bool) -> int:
    fr = ele_frame(page)
    if not fr:
        if not ele_ensure_page(page):
            return 0
        fr = ele_frame(page)
        if not fr:
            return 0
    try:
        rows = fr.evaluate(ELE_SCAN_JS)
    except Exception as exc:  # noqa: BLE001
        log(f"闪购扫描失败：{type(exc).__name__}: {exc}")
        return 0
    return handle_rows(rows, "eleme", ahead, dry, lambda: ele_click(fr))


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--watch", action="store_true", help="常驻监控")
    ap.add_argument("--interval", type=int, default=10, help="扫描间隔（秒）")
    ap.add_argument("--ahead", type=int, default=30, help="提前多少秒上报")
    ap.add_argument("--dry", action="store_true", help="只打印，不点")
    ap.add_argument("--only", choices=["both", "meituan", "ele"], default="both")
    args = ap.parse_args()

    from playwright.sync_api import sync_playwright

    with sync_playwright() as pw:
        browser = pw.chromium.connect_over_cdp(CDP_URL, timeout=60000)
        pages = [p for ctx in browser.contexts for p in ctx.pages]
        mt = next((p for p in pages if "e.waimai.meituan.com" in p.url), None)
        el_pg = ele_page(browser)
        if mt is None and el_pg is None:
            print("没有找到美团/闪购后台标签页，请先启动浏览器并登录", file=sys.stderr)
            return 2

        def once() -> int:
            n = 0
            if args.only in ("both", "meituan") and mt is not None:
                n += scan_mt(mt, args.ahead, args.dry)
            if args.only in ("both", "ele") and el_pg is not None:
                n += scan_ele(el_pg, args.ahead, args.dry)
            return n

        if not args.watch:
            print(f"完成，处理 {once()} 单")
            return 0

        log(f"开始监控（每 {args.interval} 秒，提前 {args.ahead} 秒上报，平台={args.only}）")
        last_hit = time.time()
        while True:
            try:
                n = once()
                now = time.time()
                if n:
                    last_hit = now
                if now - last_hit > 240:
                    for pg in (mt, el_pg):
                        if pg is None:
                            continue
                        try:
                            pg.reload(wait_until="domcontentloaded")
                        except Exception:  # noqa: BLE001
                            pass
                    last_hit = now
                    time.sleep(2.0)
                    if mt is not None:
                        mt_ensure_order_page(mt)
                    if el_pg is not None:
                        ele_ensure_page(el_pg)
            except Exception as exc:  # noqa: BLE001
                log(f"本轮异常：{type(exc).__name__}: {exc}")
            time.sleep(max(5, args.interval))


if __name__ == "__main__":
    raise SystemExit(main())
