from playwright.sync_api import sync_playwright
from datetime import date
import json

SHOP = 546266599
today = date.today().isoformat()
begin = f"{today} 00:00:00"
end = f"{today} 23:59:59"

JS = """
async ({begin, end, kind}) => {
    const body = {
        service: "OrderWebService", method: "queryAllOrders",
        params: {shopId: %d,
                 condition: {offset: 0, limit: 100, beginTime: begin, endTime: end},
                 allOrderQueryType: kind},
        id: "probe-" + Date.now(),
        metas: {appVersion: "1.0.0", appName: "melody",
                ksid: localStorage.getItem("ksid") || "", shopId: %d},
        ncp: "2.0.0"
    };
    const r = await fetch("https://app-api.shop.ele.me/fulfill/weborder/queryAllOrders/",
        {method: "POST", headers: {"content-type": "application/json"},
         credentials: "include", body: JSON.stringify(body)});
    const t = await r.text();
    try {
        const j = JSON.parse(t);
        const list = (j.result && j.result.orders) || [];
        return {status: r.status, n: list.length, sample: list.slice(0, 12).map(o => ({
            daySn: o.daySn, status: o.status, time: o.createdAt || o.orderTime }))};
    } catch (e) { return {status: r.status, text: t.slice(0, 200)}; }
}
""" % (SHOP, SHOP)

with sync_playwright() as p:
    b = p.chromium.connect_over_cdp("http://127.0.0.1:9222", timeout=60000)
    page = [pg for ctx in b.contexts for pg in ctx.pages if "melody.shop.ele.me" in pg.url][0]
    for kind in ("FINISHED", "ALL", "PROCESSING"):
        try:
            r = page.evaluate(JS, {"begin": begin, "end": end, "kind": kind})
            print(f"--- {kind}: 状态{r.get('status')} 数量{r.get('n')}")
            for s in (r.get("sample") or [])[:12]:
                print("     ", s)
        except Exception as e:
            print(kind, "失败", type(e).__name__, e)
    b.close()
