def _cost_of(name: str, menu: dict[str, int]) -> int | None:
    raw = str(name or "")
    if "五花肉" in raw:
        return COST_OVERRIDE["五花肉小串"] if "小串" in raw else COST_OVERRIDE["五花肉"]
    # 赠品/活动行：优先按括号里的实际菜品算（如「0元蔬菜（黄瓜）」→ 黄瓜）
    if any(k in raw for k in ("开业特惠", "赠送", "就送", "免费吃", "送")) and ("（" in raw or "(" in raw):
        import re as _re
        parts = _re.findall(r"[（(]([^）)]{1,8})[）)]", raw)
        for part in reversed(parts):
            c2 = _norm_name(part)
            if c2 and c2 in menu:
                return menu[c2]
    n = _norm_name(name)
    if not n:
        return None
    if n in menu:
        return menu[n]
    best, best_score = None, 0.0
    for k, v in menu.items():
        if not k:
            continue
        if n in k or k in n:
            score = min(len(n), len(k)) / max(len(n), len(k))
            if score > best_score:
                best, best_score = v, score
    if best is not None and best_score >= 0.5:
        return best
    # 字符重合度兜底
    for k, v in menu.items():
        common = len(set(n) & set(k))
        if common >= 3:
            score = common / max(len(set(n)), len(set(k)))
            if score > best_score and score >= 0.75:
                best, best_score = v, score
    return best


