def start(marker: str, args: list[str]) -> None:
    cmd = [str(PYW)] + args
    kw = {"cwd": str(HERE), "close_fds": True, "creationflags": NO_WIN}
    if args and args[0] == "web_app.py":
        cmd += ["--port", "8000"]
        kw["stdout"] = open(HERE / "logs" / "web_out.log", "a", encoding="utf-8")
        kw["stderr"] = open(HERE / "logs" / "web_err.log", "a", encoding="utf-8")
    else:
        name = args[0].replace(".py", "")
        kw["stderr"] = open(HERE / "logs" / f"{name}_err.log", "a", encoding="utf-8")
    subprocess.Popen(cmd, **kw)
    log(f"已拉起 {marker}")


def main() -> int:
