function renderOrders(list) {
  if (!list || !list.length) return '<div class="empty">这个区间没有订单</div>';
  return list.map((o, i) => {
    const pn = o.platform === 'meituan' ? '美团' : '闪购';
    const items = (o.items || []).map(it => {
      const diff = it.portions && Math.abs(it.portions - it.qty) > 0.01;
      return `<div class="it">
        <span class="n">${esc(it.name)}<span class="q">×${it.qty}${diff ? ' = ' + it.portions.toFixed(1) + '份' : ''}</span></span>
        <span class="c">¥${(it.cost/100).toFixed(2)}</span></div>`;
    }).join('');
    return `<div class="ord p-${o.platform}" data-i="${i}">
      <div class="hd">
        <div>
          <div class="no"><b class="idx ${o.platform === 'meituan' ? 'mt' : 'ele'}">#${o.sn != null ? o.sn : (i + 1)}</b>${o.status ? `<span class="badge ${o.st || ''}">${esc(o.status)}</span>` : ''} ${pn} · ${esc(o.time)} · 单号 ${esc(String(o.no).slice(-6))}</div>
          <div class="sum">
            <div class="cell">商品总价<b>¥${((o.gross||0)/100).toFixed(2)}</b></div>
            <div class="cell">顾客实付<b>¥${(o.paid/100).toFixed(2)}</b></div>
            <div class="cell">预计收入<b>¥${(o.income/100).toFixed(2)}</b></div>
            <div class="cell">食材成本<b>¥${(o.cost/100).toFixed(2)}</b></div>
          </div>
          <div class="sum2">
            <div class="cell ${o.profit >= 0 ? 'p' : 'm'}">预计利润<b>¥${(o.profit/100).toFixed(2)}</b></div>
            <div class="cell ${o.profit >= 0 ? 'p' : 'm'}">利润率<b>${o.income ? (o.profit / o.income * 100).toFixed(1) + '%' : '—'}</b></div>
            <div class="cell">补贴比例<b class="neg">${o.paid ? ((o.paid - o.income) / o.paid * 100).toFixed(1) + '%' : '—'}</b></div>
          </div>
        </div>
        <div class="arw">▾</div>
      </div>
      <div class="bd">${items || '<div class="it">无明细</div>'}</div>
    </div>`;
  }).join('');
}

let _lastSync = 0;

function localIso(d) {
  const p = n => String(n).padStart(2, '0');
  return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate());
}

function setSyncHint(txt) {
  const el = document.getElementById('syncHint');
  if (!el) return;
  el.textContent = txt || '';
  el.style.display = txt ? 'inline' : 'none';
}

