    pg = b.new_page(viewport={"width": 414, "height": 1000}, device_scale_factor=2)
    pg.goto("http://127.0.0.1:8000/", wait_until="networkidle", timeout=25000)
    pg.click("#plats .plat[data-k='all']"); pg.wait_for_timeout(400)
    pg.click("#ranges .range[data-k='7d']"); pg.wait_for_timeout(1800)
    pg.click("#tabs .tab[data-k='orders']"); pg.wait_for_timeout(1500)
    rows = pg.evaluate("""() => Array.from(document.querySelectorAll('.ord')).map(o => {
        const cells = Array.from(o.querySelectorAll('.sum2 .cell'));
        const m = cells.find(c => c.textContent.startsWith('利润率'));
        const no = o.querySelector('.no').innerText.split('\\n')[0];
        return m ? [no, m.querySelector('b').textContent, getComputedStyle(m.querySelector('b')).color] : null;
    }).filter(Boolean)""")
    low = [r for r in rows if r[1] != '—' and float(r[1].rstrip('%')) < 30]
    print("低于 30% 的卡片：")
    for no, t, c in low:
        print(f"   {no[:14]:16s} {t:>7}  {c}")
    print("其余抽样：", rows[0][1], rows[0][2])
    # 滚到第一个低毛利单
    if low:
        pg.evaluate("""(no) => {
            const card = Array.from(document.querySelectorAll('.ord')).find(o => o.querySelector('.no').innerText.startsWith(no));
            if (card) card.scrollIntoView({block:'center'});
        }""", low[0][0].split(' ')[0])
        pg.wait_for_timeout(500)
    pg.screenshot(path=str(out / "final_69_margin_red.png"))
    b.close()
