from playwright.sync_api import sync_playwright
with sync_playwright() as p:
    b = p.chromium.connect_over_cdp("http://127.0.0.1:9222", timeout=30000)
    pg = next(pg for ctx in b.contexts for pg in ctx.pages if "e.waimai.meituan.com" in pg.url)
    shell = pg.frames[0]
    info = shell.evaluate("""() => {
        const out = [];
        const walk = (root, depth) => {
            for (const el of root.querySelectorAll('*')) {
                const t = (el.innerText || '').trim();
                if (t && t.length < 12 && t.includes('订单管理')) {
                    out.push({tag: el.tagName, cls: String(el.className).slice(0,60),
                              kids: el.children.length, text: t,
                              html: el.outerHTML.slice(0, 220)});
                }
            }
        };
        walk(document, 0);
        return out.slice(0, 6);
    }""")
    for x in info:
        print(x, "\n")
    b.close()
