from playwright.sync_api import sync_playwright
import time
with sync_playwright() as p:
    b = p.chromium.connect_over_cdp("http://127.0.0.1:9222", timeout=30000)
    pg = next(pg for ctx in b.contexts for pg in ctx.pages if "e.waimai.meituan.com" in pg.url)
    fr = pg.main_frame
    info = fr.evaluate("""() => {
        const items = Array.from(document.querySelectorAll("div[class*='menu-item']"));
        const target = items.find(e => (e.textContent || '').includes('订单管理'));
        if (!target) return {err: 'no menu'};
        ['mouseenter','mouseover','mousemove'].forEach(t =>
            target.dispatchEvent(new MouseEvent(t, {bubbles: true, view: window})));
        const all = Array.from(document.querySelectorAll('*'))
            .filter(e => (e.textContent || '').trim() === '全部订单');
        return {
            cls: String(target.className),
            found: all.length,
            sample: all.slice(0,3).map(e => ({
                tag: e.tagName, cls: String(e.className).slice(0,40),
                visible: e.offsetParent !== null,
                rect: (() => { const r = e.getBoundingClientRect(); return [Math.round(r.x), Math.round(r.y), Math.round(r.width)]; })()
            }))
        };
    }""")
    print(info)
    time.sleep(1)
    print("hover 后含全部订单:", "全部订单" in fr.inner_text("body"))
    b.close()
'@ | Set-Content scripts\debug_menu2.py -Encoding utf8
