        body = fr.inner_text("body")
        if "全部订单" in body:
            print(f"{i+1}s 后出现全部订单")
            break
    else:
        print("仍未出现；当前文本:", fr.inner_text("body")[:200].replace("\n"," | "))
    cnt = fr.locator("text=全部订单").count()
    print("全部订单元素数:", cnt)
    if cnt:
        fr.locator("text=全部订单").first.click(timeout=10000)
        time.sleep(4)
        import sys
        sys.path.insert(0, ".")
        import auto_meal
        print("订单页 iframe:", bool(auto_meal.mt_frame(pg)))
    b.close()
