import io, re
p = "auto_meal.py"
s = io.open(p, encoding="utf-8").read()

new_fn = '''MT_ORDER_URL = ("https://e.waimai.meituan.com/new_fe/orderbusiness"
                 "#/order/history?region_id=1000350300&region_version=1792542949")


def mt_ensure_order_page(page) -> bool:
    """确保美团在「全部订单」页。优先直连，失败再走左侧菜单。"""
    if mt_frame(page):
        return True

    # 路线 A：直接打开订单页 URL（最快最稳）
    try:
        page.goto(MT_ORDER_URL, wait_until="domcontentloaded", timeout=30000)
        for _ in range(10):
            time.sleep(1.5)
            if mt_frame(page):
                return True
    except Exception as exc:  # noqa: BLE001
        log(f"美团直连订单页失败：{type(exc).__name__}: {exc}")

    # 路线 B：回首页 → 点「订单管理」展开二级菜单 → 点「全部订单」
    try:
        page.goto("https://e.waimai.meituan.com/", wait_until="domcontentloaded", timeout=30000)
        time.sleep(3.0)
    except Exception:  # noqa: BLE001
        pass

    for attempt in range(3):
        try:
            shell = page.main_frame
            shell.evaluate("""() => {
                const el = Array.from(document.querySelectorAll("div[class*='menu-item']"))
                    .find(e => (e.textContent || '').includes('订单管理'));
                if (el) el.click();
            }""")
            for _ in range(8):
                time.sleep(1.0)
                if "全部订单" in shell.inner_text("body"):
                    break
            shell.locator("text=全部订单").first.click(timeout=10000)
            for _ in range(10):
                time.sleep(1.5)
                if mt_frame(page):
                    return True
        except Exception as exc:  # noqa: BLE001
            log(f"美团菜单打开订单页失败（第 {attempt + 1} 次）：{type(exc).__name__}: {exc}")
            time.sleep(2.0)
    return mt_frame(page) is not None


'''
m = re.search(r"def mt_ensure_order_page\(page\) -> bool:.*?(?=\ndef )", s, re.S)
assert m, "未找到函数"
s = s[:m.start()] + new_fn + s[m.end() + 1:]
io.open(p, "w", encoding="utf-8").write(s)
print("mt_ensure_order_page 已重写（直连 + 菜单兜底）")
