def compose_ele(date: str, rows: list[dict]) -> str:
    """把闪购核对结果写成微信短消息。"""
    if not rows:
        return f"**出餐核对 · {date[5:]}**\n闪购当天没有订单记录。"
    over = [r for r in rows if r["超时"]]
    done = [r for r in rows if r["已出餐"]]
    lines = [f"**出餐核对 · {date[5:]}**",
             f"闪购 {len(rows)} 单，已出餐 {len(done)} 单，"
             f"准时 {len(rows) - len(over)} 单，超时 **{len(over)}** 单"]
    if over:
        lines.append("")
        for r in over:
            used = f"{r['用时秒'] // 60}分{r['用时秒'] % 60:02d}秒" if r["用时秒"] else "—"
            lines.append(f"❌ #{r['sn']} {r['下单']}下单 建议{r['建议']} "
                         f"实际{r['出餐']}（用时{used}）")
    else:
        lines.append("全部按时出餐 ✅")
    return "\n".join(lines)


