def mt_rows(page):
    """美团订单页里「已出餐 用时X:XX / 参考出餐时长 Y分Z秒」的解析（仅近两日可读）。"""
    fr = None
    for f in page.frames:
        try:
            if "orderbusiness" in f.url and len(f.inner_text("body")) > 1000:
                fr = f
                break
        except Exception:  # noqa: BLE001
            continue
    if fr is None:
        return None
    try:
        txt = fr.inner_text("body")
    except Exception:  # noqa: BLE001
        return None
    rows = []
    for blk in re.split(r"(?=#\d)", txt):
        m = re.match(r"#(\d+)", blk)
        if not m:
            continue
        u = re.search(r"已出餐\s*用时\s*(\d{1,2}):(\d{2})", blk)
        r = re.search(r"参考出餐时长\s*(?:(\d+)分)?\s*(\d+)秒", blk)
        if not (u and r):
            continue
        used = int(u.group(1)) * 60 + int(u.group(2))
        ref = int(r.group(1) or 0) * 60 + int(r.group(2))
        rows.append({"sn": m.group(1), "用时秒": used, "参考秒": ref,
                     "超时": used > ref})
    return rows


def run_once(date: str, with_log: bool, notify: bool) -> int:
    rc = scan(date, with_log, notify=False)

    # 美团：只能读页面（近两日），读不到就跳过
    mt = None
    try:
        with sync_playwright() as pw:
            browser = pw.chromium.connect_over_cdp(CDP, timeout=30000)
            page = None
            for ctx in browser.contexts:
                for p in ctx.pages:
                    if "e.waimai.meituan.com" in p.url and "orderbusiness" in p.url:
                        page = p
                        break
                if page:
                    break
            if page is not None:
                mt = mt_rows(page)
            browser.close()
    except Exception as exc:  # noqa: BLE001
        print(f"美团出餐数据读取失败：{type(exc).__name__}: {exc}")

    lines = []
    if mt:
        over = [r for r in mt if r["超时"]]
        lines.append(f"美团 {len(mt)} 单，准时 {len(mt) - len(over)}，超时 **{len(over)}**")
        for r in over:
            lines.append(f"❌ #{r['sn']} 用时{r['用时秒'] // 60}:{r['用时秒'] % 60:02d} "
                         f"参考{r['参考秒'] // 60}:{r['参考秒'] % 60:02d}")
