def _dsh_live_ports() -> list[int]:
    """自动找出 DeepSeek Harness 本次监听的端口（每次启动端口会变）。"""
    global _DSH_PORTS
    if _DSH_PORTS:
        return _DSH_PORTS
    ps = (
        "Get-NetTCPConnection -State Listen -LocalAddress 127.0.0.1 "
        "-ErrorAction SilentlyContinue | ForEach-Object { "
        "$p = Get-Process -Id $_.OwningProcess -ErrorAction SilentlyContinue; "
        "if ($p -and $p.ProcessName -like '*DeepSeek*') { $_.LocalPort } }"
    )
    try:
        out = subprocess.run(
            ["powershell.exe", "-NoProfile", "-NonInteractive", "-Command", ps],
            capture_output=True, text=True, timeout=20,
            creationflags=0x08000000,
        ).stdout
        ports = sorted({int(x) for x in out.split() if x.strip().isdigit()})
        _DSH_PORTS = ports
        return ports
    except Exception:  # noqa: BLE001
        return []


def _dsh_host_candidates(cfg: dict) -> list[str]:
    """DSH Host 的地址：配置优先，其次环境变量，再自动探测，最后常见端口。"""
    out: list[str] = []
    base = (cfg.get("dsh_host") or "").rstrip("/")
    if base:
