function Probe($url, $method = "GET", $body = $null) {
  try {
    $p = @{ Uri = $url; Method = $method; TimeoutSec = 8; UseBasicParsing = $true }
    if ($body) { $p["Body"] = $body; $p["ContentType"] = "application/json" }
    $r = Invoke-WebRequest @p -ErrorAction Stop
    "$method $url → $($r.StatusCode) $((($r.Content) -replace '\s+',' ').Substring(0, [Math]::Min(160, $r.Content.Length)))"
  } catch {
    $resp = $_.Exception.Response
    if ($resp) {
      try { $sr = New-Object System.IO.StreamReader($resp.GetResponseStream()); $txt = $sr.ReadToEnd() } catch { $txt = "" }
      "$method $url → $([int]$resp.StatusCode) $((($txt) -replace '\s+',' ').Substring(0, [Math]::Min(160, $txt.Length)))"
    } else { "$method $url → 失败 $($_.Exception.Message)" }
  }
}
